        <select id="af-acao" onchange="filtrarAudit()" style="flex:1;min-width:120px;padding:8px;border:1px solid var(--br);border-radius:6px;background:var(--cd2);color:var(--tx)"><option value="">Todas as ações</option></select>
        <select id="af-mod" onchange="filtrarAudit()" style="flex:1;min-width:120px;padding:8px;border:1px solid var(--br);border-radius:6px;background:var(--cd2);color:var(--tx)"><option value="">Todos os módulos</option></select>
        <select id="af-mes" onchange="filtrarAudit()" style="flex:1;min-width:120px;padding:8px;border:1px solid var(--br);border-radius:6px;background:var(--cd2);color:var(--tx)"><option value="">Todos os meses</option></select>
