        <div class="fg" id="prz-dias-box"><label>Dias (separar por /)</label><input id="prz-dias" placeholder="30/60/90"></div>
        <div class="fg" id="prz-parc-box" style="display:none"><label>Nº de Parcelas</label><input type="number" id="prz-parc" placeholder="3"></div>
        <div class="fg" id="prz-int-box" style="display:none"><label>Intervalo (dias)</label><input type="number" id="prz-int-dias" placeholder="28"></div>
        <div class="fg" id="prz-int-qtd-box" style="display:none"><label>Qtd. Vezes</label><input type="number" id="prz-int-qtd" placeholder="2"></div>
