  <div style="margin-bottom:10px"><input type="search" placeholder="🔍 Buscar por cliente, placa..." oninput="filtrarTabela(this,'prej-tb')" style="width:100%;max-width:400px;padding:9px 12px;border:1px solid var(--br);border-radius:8px;background:var(--cd2);color:var(--tx);font-size:13px"></div>
