        <option value="vigente">🟢 Vigente</option>
        <option value="finalizado">✅ Finalizado</option>
      </select>
    </div>
    
    <div class="fg"><label>Observações</label><textarea id="mob-obs" rows="2"></textarea></div>
    
    <div style="margin-top:12px">
