        <div class="fr"><div class="fg"><label>Marca</label><input id="mob-p1-mk" data-ac="marcaPneu"></div><div class="fg"><label>Nº MH3</label><input id="mob-p1-num"></div><div class="fg"><label>Medida</label><input id="mob-p1-med"></div><div class="fg"><label>Reformado</label><select id="mob-p1-ref"><option value="nao">Não</option><option value="sim">Sim</option></select></div></div>
      </div>
      <div style="background:var(--cd2);border-radius:8px;padding:10px;margin-bottom:8px">
        <div style="font-size:11px;font-weight:700;color:var(--mt)">2º EIXO</div>
        <div class="fr"><div class="fg"><label>Marca</label><input id="mob-p2-mk" data-ac="marcaPneu"></div><div class="fg"><label>Nº MH3 (até 4)</label><input id="mob-p2-num"></div><div class="fg"><label>Medida</label><input id="mob-p2-med"></div><div class="fg"><label>Reformado</label><select id="mob-p2-ref"><option value="nao">Não</option><option value="sim">Sim</option></select></div></div>
      </div>
      <div style="background:var(--cd2);border-radius:8px;padding:10px;margin-bottom:8px">
        <div style="font-size:11px;font-weight:700;color:var(--mt)">3º EIXO</div>
        <div class="fr"><div class="fg"><label>Marca</label><input id="mob-p3-mk" data-ac="marcaPneu"></div><div class="fg"><label>Nº MH3 (até 4)</label><input id="mob-p3-num"></div><div class="fg"><label>Medida</label><input id="mob-p3-med"></div><div class="fg"><label>Reformado</label><select id="mob-p3-ref"><option value="nao">Não</option><option value="sim">Sim</option></select></div></div>
