function saveEstq(){const ds=document.getElementById('estq-ds').value.trim();if(!ds){toast('Informe a descrição','er');return;}const eid=document.getElementById('estq-eid').value;const data={cd:document.getElementById('estq-cd').value||gerarCodEstqAuto(),
    cat:document.getElementById('estq-cat').value,ds,
    tabVenda:document.getElementById('estq-tab-venda')?document.getElementById('estq-tab-venda').value:'final',
    margem:document.getElementById('estq-margem')?parseFloat(document.getElementById('estq-margem').value)||40:40,
    nfNum:document.getElementById('estq-nf-num')?document.getElementById('estq-nf-num').value:'',qt:parseFloat(document.getElementById('estq-qt').value)||0,mn:parseFloat(document.getElementById('estq-mn').value)||0,un:document.getElementById('estq-un').value,cv:parseFloat(document.getElementById('estq-cv').value)||0,pv:parseFloat(document.getElementById('estq-pv').value)||0,loc:document.getElementById('estq-loc').value};if(eid){const idx=D.estoque.findIndex(x=>x.id===eid);if(idx>-1)D.estoque[idx]={...D.estoque[idx],...data};}else{data.id=uid();D.estoque.push(data);}document.getElementById('estq-eid').value='';sv();closeM('m-estq');toast('Item salvo!');rdEstq();}
function openEditEstq(id){if(_bloqEditar('estq'))return;reqSenha(()=>{const e=D.estoque.find(x=>x.id===id);if(!e)return;document.getElementById('estq-eid').value=id;document.getElementById('estq-mtitle').textContent='✏️ Editar Item';['cd','ds','loc'].forEach(k=>{const el=document.getElementById('estq-'+k);if(el)el.value=e[k]||'';});['cat','un'].forEach(k=>{const el=document.getElementById('estq-'+k);if(el)el.value=e[k]||el.options[0].value;});['qt','mn','cv','pv'].forEach(k=>{const el=document.getElementById('estq-'+k);if(el)el.value=e[k]||0;});document.getElementById('m-estq').classList.add('op');});}
function delEstq(id){reqSenha(()=>{if(!confirm('Excluir item?'))return;var _it=D.estoque.find(x=>x.id===id);if(typeof auditarExclusao==='function')auditarExclusao('estoque','Excluiu item: '+((_it&&(_it.ds||_it.nome||_it.cd))||id));D.estoque=D.estoque.filter(x=>x.id!==id);sv();rdEstq();});}
function mvEstq(id,d){const e=D.estoque.find(x=>x.id===id);if(!e)return;const n=parseFloat(prompt('Quantidade a '+(d>0?'adicionar':'retirar')+':','1')||0);if(!n)return;e.qt=Math.max(0,e.qt+(n*d));sv();rdEstq();}

// ============ NF & XML ============
function addNfI(){const desc=prompt('Descrição:');if(!desc)return;const qtd=parseFloat(prompt('Qtd:','1')||1);const val=parseFloat(prompt('Valor unit. (R$):','0')||0);nfIs.push({id:uid(),desc,qtd,val});rdNfIs();}
function rdNfIs(){const el=document.getElementById('nf-items-list');if(!el)return;if(!nfIs.length){el.innerHTML='<div style="font-size:10px;color:var(--mt)">Adicione itens</div>';return;}el.innerHTML=nfIs.map(i=>`<div class="lanc-row"><div><div style="font-size:11px;font-weight:500">${i.desc}</div><div style="font-size:9px;color:var(--mt)">${i.qtd}x · ${fmt(i.val)}</div></div><span style="font-family:'Barlow Condensed';font-size:12px;font-weight:700">${fmt(i.qtd*i.val)}</span></div>`).join('');}
function saveNf(){const num=document.getElementById('nf-num').value.trim();if(!num){toast('Informe o nº NF','er');return;}const cp=document.querySelector('input[name="nf-cp"]:checked');const nf={id:uid(),num,dt:document.getElementById('nf-dt').value,forn:document.getElementById('nf-forn').value,cnpj:document.getElementById('nf-cnpj').value,items:[...nfIs],vl:parseFloat(document.getElementById('nf-vl').value)||0,vc:document.getElementById('nf-vc').value,cp:cp?cp.value:'sim',st:'pendente',ob:document.getElementById('nf-ob').value};D.nfs.push(nf);nfIs.forEach(i=>{const f=D.estoque.find(e=>e.ds.toLowerCase()===i.desc.toLowerCase());if(f)f.qt+=i.qtd;});sv();closeM('m-nf');toast('NF '+num+' registrada!');rdNf();rdEstq();rdFin();}
function delNf(id){reqSenha(()=>{if(!confirm('Excluir NF?'))return;auditarExclusao('nf','NF excluída');D.nfs=D.nfs.filter(x=>x.id!==id);sv();rdNf();toast('NF excluída.');});}
function parseXML(){const txt=document.getElementById('xml-inp').value.trim();if(!txt){toast('Cole o XML','er');return;}try{const parser=new DOMParser();const xml=parser.parseFromString(txt,'text/xml');const get=(tag)=>{const el=xml.getElementsByTagName(tag)[0];return el?el.textContent:''};const nf={id:uid(),num:get('nNF')||get('cNF')||'XML',dt:get('dhEmi').split('T')[0]||today(),forn:get('xNome'),cnpj:get('CNPJ'),items:[],vl:parseFloat(get('vNF')||get('vProd'))||0,vc:today(),cp:'sim',st:'pendente',ob:'Importado via XML'};const prods=xml.getElementsByTagName('det');Array.from(prods).forEach(det=>{const ds=det.getElementsByTagName('xProd')[0]?.textContent||'Item';const qtd=parseFloat(det.getElementsByTagName('qCom')[0]?.textContent||1);const val=parseFloat(det.getElementsByTagName('vUnCom')[0]?.textContent||0);nf.items.push({id:uid(),desc:ds,qtd,val});const f=D.estoque.find(e=>e.ds.toLowerCase()===ds.toLowerCase());if(f)f.qt+=qtd;});D.nfs.push(nf);sv();closeM('m-xml');toast(`NF ${nf.num} importada com ${nf.items.length} item(s)!`);rdNf();rdEstq();}catch(e){toast('Erro ao processar XML. Verifique o formato.','er');}}

// ============ DESPESA ============


function togglePrazoManualDesp(){
  const v=document.getElementById('desp-prazo-sel').value;
  const box=document.getElementById('desp-prazo-man-box');
  if(box)box.style.display=v==='__manual__'?'':'none';
}

function togglePrazoDesp(){
  const v=document.getElementById('desp-pag').value;
  const box=document.getElementById('desp-prazo-box');
  if(box) box.style.display=v==='prazo'?'':'none';
  if(v==='prazo'){
    const sel=document.getElementById('desp-prazo-sel');
    if(sel){
      sel.innerHTML='<option value="">Selecionar prazo...</option><option value="__manual__">✏️ Digitar prazo manual</option>';
      (D.config.prazos||[]).forEach(p=>{sel.innerHTML+=`<option value="${p.id}">${p.nome} (${p.detalhe})</option>`;});
    }
  }
}

function saveDesp(){const desc=document.getElementById('desp-desc').value.trim();if(!desc){toast('Informe a descrição','er');return;}const eid=document.getElementById('desp-eid').value;const doc=document.querySelector('input[name="desp-doc"]:checked');const flx=null; /* fluxo automático: sempre sim, exceto atrasado */const pag=document.getElementById('desp-pag')?document.getElementById('desp-pag').value:'eletronico';const prazoSel=document.getElementById('desp-prazo-sel')?document.getElementById('desp-prazo-sel').value:'';const data={desc,pag,prazoSel,cp:'sim',dt:document.getElementById('desp-dt').value,cat:document.getElementById('desp-cat').value,placa:document.getElementById('desp-placa').value,forn:document.getElementById('desp-forn').value,vl:parseFloat(document.getElementById('desp-vl').value)||0,vc:document.getElementById('desp-vc').value,doc:doc?doc.value:'Avulso',ndoc:document.getElementById('desp-ndoc').value,st:document.getElementById('desp-st').value,fluxo:'sim'};if(eid){
    const idx=D.despesas.findIndex(x=>x.id===eid);
    if(idx>-1)D.despesas[idx]={...D.despesas[idx],...data};
  }else if(pag==='prazo'&&prazoSel){
    // BUG CORRIGIDO: prazo com parcelas/dias gera MÚLTIPLOS lançamentos no Contas a Pagar
    let prz=(D.config.prazos||[]).find(p=>p.id===prazoSel);
    if(prazoSel==='__manual__'){
      const man=document.getElementById('desp-prazo-man')?document.getElementById('desp-prazo-man').value.trim():'';
      if(man)prz={tipo:'dias',detalhe:man};
    }
    let parcelas=[];
    if(prz){
      if(prz.tipo==='parcelas'){
        // Ex: 2x → 2 lançamentos mensais
        const n=parseInt(prz.detalhe)||1;
        const base=data.vc?new Date(data.vc+'T12:00'):new Date();
        for(let i=0;i<n;i++){
          const dt=new Date(base);dt.setMonth(dt.getMonth()+i);
          parcelas.push({vcParc:dt.toISOString().substring(0,10),nParc:i+1,total:n});
        }
      }else{
        // dias ou intervalo: ex 28/56 → lançamento a cada data
        const dias=String(prz.detalhe).split('/').map(d=>parseInt(d)).filter(d=>d>0);
        const base=data.dt?new Date(data.dt+'T12:00'):new Date();
        dias.forEach((d,i)=>{
          const dt=new Date(base);dt.setDate(dt.getDate()+d);
          parcelas.push({vcParc:dt.toISOString().substring(0,10),nParc:i+1,total:dias.length});
        });
      }
    }
    if(parcelas.length>1){
      const vlParc=Math.round((data.vl/parcelas.length)*100)/100;
      parcelas.forEach(p=>{
        D.despesas.push({...data,id:uid(),
          desc:data.desc+' — Parcela '+p.nParc+'/'+p.total,
          vl:vlParc,vc:p.vcParc,parcela:p.nParc,totalParc:p.total});
      });
      toast(parcelas.length+' lançamentos gerados no Contas a Pagar ('+fmt(vlParc)+' cada)!','ok');
    }else{
      data.id=uid();D.despesas.push(data);
    }
  }else{
    data.id=uid();D.despesas.push(data);
  }document.getElementById('desp-eid').value='';auditar(eid?'ALTERACAO':'CRIACAO','despesas',(eid?'Despesa ALTERADA':'Despesa criada')+': '+desc+' '+fmt(parseFloat(document.getElementById('desp-vl').value)||0));sv();closeM('m-desp');toast('Despesa salva!');rdDesp();rdFin();}
function openEditDesp(id){if(_bloqEditar('desp'))return;reqSenha(()=>{const e=D.despesas.find(x=>x.id===id);if(!e)return;popSels();document.getElementById('desp-eid').value=id;document.getElementById('desp-mtitle').textContent='✏️ Editar Despesa';document.getElementById('desp-desc').value=e.desc||'';document.getElementById('desp-dt').value=e.dt||'';document.getElementById('desp-cat').value=e.cat||'Outros';document.getElementById('desp-placa').value=e.placa||'';document.getElementById('desp-forn').value=e.forn||'';document.getElementById('desp-vl').value=e.vl||0;document.getElementById('desp-vc').value=e.vc||'';document.getElementById('desp-ndoc').value=e.ndoc||'';document.getElementById('desp-st').value=e.st||'pendente';const de=document.querySelector(`input[name="desp-doc"][value="${e.doc||'Avulso'}"]`);if(de)de.checked=true;document.getElementById('m-desp').classList.add('op');});}
function delDesp(id){reqSenha(()=>{if(!confirm('Excluir despesa?'))return;auditarExclusao('despesas','Despesa excluída');D.despesas=D.despesas.filter(x=>x.id!==id);sv();rdDesp();rdFin();toast('Excluída.');});}
function advDesp(id){const d=D.despesas.find(x=>x.id===id);if(!d)return;d.st=d.st==='pago'?'pendente':'pago';sv();rdDesp();rdFin();}
function pagarNf(id){const n=D.nfs.find(x=>x.id===id);if(!n)return;n.st='pago';sv();rdNf();rdFin();toast('NF marcada como paga.');}

// ============ REVISÃO ============
function abrirPatioContato(eqId){var e=(D.equips||[]).find(function(x){return x.id===eqId;});if(!e){toast('Veículo não encontrado','er');return;}var pt=e.patio||{};document.getElementById('patio-eqid').value=eqId;document.getElementById('patio-resp-nome').value=pt.respNome||'';document.getElementById('patio-resp-tel').value=pt.respTel||'';document.getElementById('patio-mot-nome').value=pt.motNome||'';document.getElementById('patio-mot-tel').value=pt.motTel||'';document.getElementById('patio-obs').value=pt.obs||'';openM('m-patio-contato');}
function savePatioContato(){var eqId=document.getElementById('patio-eqid').value;var e=(D.equips||[]).find(function(x){return x.id===eqId;});if(!e){toast('Veículo não encontrado','er');return;}e.patio={respNome:document.getElementById('patio-resp-nome').value.trim(),respTel:document.getElementById('patio-resp-tel').value.trim(),motNome:document.getElementById('patio-mot-nome').value.trim(),motTel:document.getElementById('patio-mot-tel').value.trim(),obs:document.getElementById('patio-obs').value.trim()};if(!(e.patio.respNome||e.patio.respTel||e.patio.motNome||e.patio.motTel||e.patio.obs))delete e.patio;sv();closeM('m-patio-contato');if(typeof rdRev==='function')rdRev();toast('Contato salvo!','ok');}
function excluirPatioContato(eqId){if(!confirm('Excluir o contato do contratante deste veículo?'))return;var e=(D.equips||[]).find(function(x){return x.id===eqId;});if(!e)return;delete e.patio;sv();if(typeof rdRev==='function')rdRev();toast('Contato excluído.','ok');}
function openRevLanc(eqId){const eq=D.equips.find(e=>e.id===eqId);if(!eq)return;document.getElementById('rev-eqid').value=eqId;document.getElementById('rev-eq-lbl').value=`${eq.placa} — ${eq.mk} ${eq.mo}`;document.getElementById('rev-dt').value=today();document.getElementById('rev-km').value='';document.getElementById('rev-hr').value='';document.getElementById('rev-ob').value='';var _rr=document.getElementById('rev-revisao');if(_rr)_rr.checked=false;openM('m-rev');}
function limparReiniciarRevisoes(){
  if(typeof ehAdminAtual==='function' && !ehAdminAtual()){toast('Só o administrador pode reiniciar o acompanhamento','er');return;}
  if(!confirm('Reiniciar o acompanhamento de revisão?\n\n• Apaga TODOS os lançamentos de KM/horímetro do acompanhamento\n• Define a ÚLTIMA REVISÃO de cada veículo = KM/horímetro INICIAL do cadastro\n• A próxima revisão passa a contar a partir daí\n\nO cadastro de veículos e as Ordens de Serviço NÃO são afetados.')) return;
  var idsAntigos=(D.revisoes||[]).map(function(r){return r&&r.id;}).filter(function(x){return x!=null&&x!=='';});
  D.revisoes=[];
  var n=0;
  (D.equips||[]).forEach(function(e){if(!e)return;e.urKm=parseInt(_numLimpo(e.km))||0;e.urHr=parseInt(_numLimpo(e.hr))||0;e.urDt=e.kmDt||'';n++;});
  // Apaga as revisões antigas DIRETO no servidor (garante que não voltem ao sincronizar)
  if(syncAtivo && authToken && idsAntigos.length){ try{ syncSalvar('revisoes', [], idsAntigos); }catch(e){} }
  window._sidsServer=window._sidsServer||{}; window._sidsServer['revisoes']=[];
  window._modJson=window._modJson||{}; window._modJson['revisoes']='[]';
  if(typeof auditar==='function')auditar('ALTERACAO','revisao','Reiniciou o acompanhamento de revisão de '+n+' veículo(s) — apagou '+idsAntigos.length+' lançamento(s) (última revisão = KM inicial)');
  sv();if(typeof updPendCnt==='function')updPendCnt();rdRev();
  toast('Acompanhamento reiniciado! '+idsAntigos.length+' lançamento(s) apagado(s).');
}
function saveRev(){const eqId=document.getElementById('rev-eqid').value;const eq=D.equips.find(e=>e.id===eqId);if(!eq)return;if(!D.revisoes)D.revisoes=[];var _rkm=parseFloat(document.getElementById('rev-km').value)||0;var _rhr=parseFloat(document.getElementById('rev-hr').value)||0;var _rdt=document.getElementById('rev-dt').value;D.revisoes.push({id:uid(),eqId,placa:eq.placa,km:_rkm,hr:_rhr,dt:_rdt,ob:document.getElementById('rev-ob').value});var _ehRev=!!(document.getElementById('rev-revisao')&&document.getElementById('rev-revisao').checked);if(_ehRev){eq.urKm=_rkm;eq.urHr=_rhr;eq.urDt=_rdt||eq.urDt||'';if(typeof auditar==='function')auditar('ALTERACAO','revisao','Registrou revisão de '+(eq.placa||eq.id)+' ('+_rkm+'km / '+_rhr+'h) — reinicia contagem');}sv();closeM('m-rev');toast(_ehRev?'Revisão registrada! Contagem reiniciada.':'Lançamento salvo!');updPendCnt();rdRev();}

// ============ CHECKLIST ============
function addClItemM(){const inp=document.getElementById('cl-new-item');const t=inp.value.trim();if(!t)return;clIMs.push({id:uid(),txt:t});inp.value='';rdClIMs();}
function toggleImportCl(){var a=document.getElementById('cl-import-area');if(a)a.style.display=(a.style.display==='none'||!a.style.display)?'block':'none';}
function importarClItens(){var t=document.getElementById('cl-import-txt');var linhas=(t.value||'').split('\n').map(function(l){return l.replace(/^\s*\d+[\.\)\-]\s*/,'').replace(/^[•\-\*►▸>]+\s*/,'').trim();}).filter(function(l){return l;});if(!linhas.length){toast('Cole ao menos um item','er');return;}linhas.forEach(function(l){clIMs.push({id:uid(),txt:l});});t.value='';document.getElementById('cl-import-area').style.display='none';rdClIMs();toast(linhas.length+' itens adicionados');}
function rdClIMs(){const el=document.getElementById('cl-items-list');if(!el)return;el.innerHTML=clIMs.map((i,idx)=>`<div style="display:flex;align-items:center;gap:5px;padding:5px 7px;background:var(--cd2);border:1px solid var(--br);border-radius:3px;margin-bottom:3px"><span style="font-size:11px;flex:1">${i.txt}</span><button class="btn bg btn-xs" onclick="moveClIM('${i.id}',-1)" ${idx===0?'disabled':''} title="Subir">↑</button><button class="btn bg btn-xs" onclick="moveClIM('${i.id}',1)" ${idx===clIMs.length-1?'disabled':''} title="Descer">↓</button><button class="btn bd btn-xs" onclick="rmClIM('${i.id}')" title="Excluir">×</button></div>`).join('');}
function rmClIM(id){clIMs=clIMs.filter(x=>x.id!==id);rdClIMs();}
function moveClIM(id,dir){const idx=clIMs.findIndex(x=>x.id===id);if(idx<0)return;const novo=idx+dir;if(novo<0||novo>=clIMs.length)return;const t=clIMs[idx];clIMs[idx]=clIMs[novo];clIMs[novo]=t;rdClIMs();}
function saveCl(){const nm=document.getElementById('cl-nm').value.trim();if(!nm){toast('Informe o nome','er');return;}const inp=document.getElementById('cl-new-item');if(inp.value.trim()){clIMs.push({id:uid(),txt:inp.value.trim()});inp.value='';}var _imp=document.getElementById('cl-import-txt');if(_imp&&_imp.value.trim()){var _ls=_imp.value.split('\n').map(function(l){return l.replace(/^\s*\d+[\.\)\-]\s*/,'').replace(/^[•\-\*►▸>]+\s*/,'').trim();}).filter(function(l){return l;});_ls.forEach(function(l){clIMs.push({id:uid(),txt:l});});_imp.value='';}const eid=document.getElementById('cl-eid').value;if(eid){const cl=D.checklists.find(c=>c.id===eid);if(cl){cl.nm=nm;cl.cat=document.getElementById('cl-cat').value;cl.items=[...clIMs];}}else{D.checklists.push({id:uid(),nm,cat:document.getElementById('cl-cat').value,items:[...clIMs]});}sv();closeM('m-cl');toast(eid?'Checklist atualizado!':'Checklist salvo!');rdCl();}
function delCl(id){reqSenha(()=>{if(!confirm('Excluir?'))return;if(typeof auditarExclusao==='function')auditarExclusao('checklist','Excluiu checklist: '+id);D.checklists=D.checklists.filter(c=>c.id!==id);sv();rdCl();});}
function addClIE(id){const inp=document.getElementById('clnew-'+id);const t=inp.value.trim();if(!t)return;const cl=D.checklists.find(c=>c.id===id);if(!cl)return;cl.items.push({id:uid(),txt:t});inp.value='';sv();rdCl();}
function editCl(id){const cl=D.checklists.find(c=>c.id===id);if(!cl)return;openM('m-cl');document.getElementById('cl-eid').value=id;document.getElementById('cl-nm').value=cl.nm;document.getElementById('cl-cat').value=cl.cat;clIMs=cl.items.map(i=>({id:i.id,txt:i.txt}));rdClIMs();}
function editClItem(clId,itemId){window._clEditItem={cl:clId,item:itemId};rdCl();setTimeout(()=>{const e=document.getElementById('cledit-'+itemId);if(e){e.focus();e.select();}},30);}
function cancelarEdicaoItem(){window._clEditItem=null;rdCl();}
function salvarEdicaoItem(clId,itemId){const cl=D.checklists.find(c=>c.id===clId);if(!cl)return;const it=cl.items.find(i=>i.id===itemId);if(!it)return;const inp=document.getElementById('cledit-'+itemId);const t=(inp.value||'').trim();if(!t){toast('Texto vazio','er');return;}it.txt=t;window._clEditItem=null;sv();rdCl();toast('Item atualizado');}
function delClItem(clId,itemId){const cl=D.checklists.find(c=>c.id===clId);if(!cl)return;cl.items=cl.items.filter(i=>i.id!==itemId);sv();rdCl();}
function moveClItem(clId,itemId,dir){const cl=D.checklists.find(c=>c.id===clId);if(!cl)return;const idx=cl.items.findIndex(i=>i.id===itemId);if(idx<0)return;const novo=idx+dir;if(novo<0||novo>=cl.items.length)return;const t=cl.items[idx];cl.items[idx]=cl.items[novo];cl.items[novo]=t;sv();rdCl();}
function clDragStart(ev,clId,idx){window._clDrag={cl:clId,idx:idx};ev.dataTransfer.effectAllowed='move';try{ev.dataTransfer.setData('text','x');}catch(e){}}
function clDragOver(ev){ev.preventDefault();ev.dataTransfer.dropEffect='move';}
function clDrop(ev,clId,idx){ev.preventDefault();if(!window._clDrag||window._clDrag.cl!==clId)return;const cl=D.checklists.find(c=>c.id===clId);if(!cl)return;const from=window._clDrag.idx,to=idx;window._clDrag=null;if(from===to)return;const item=cl.items.splice(from,1)[0];cl.items.splice(to,0,item);sv();rdCl();}

// ============ USUÁRIO ============
function setPP(){const pf=document.getElementById('usr-pf').value;const perms={admin:['dash','frota','manut','cts','meds','vend','estq','desp','fin','rel','adm'],operacional:['dash','frota','manut'],motorista:['dash'],financeiro:['dash','meds','vend','desp','fin','rel']};const all=['dash','frota','manut','cts','meds','vend','estq','desp','fin','rel','adm'];all.forEach(p=>{const el=document.getElementById('pr-'+p);if(el){if(pf==='admin'||(perms[pf]&&perms[pf].includes(p)))el.classList.add('on');else el.classList.remove('on');}});}

function openNovoUsr(){
  document.getElementById('usr-eid').value='';
  document.getElementById('usr-nm').value='';
  document.getElementById('usr-lg').value='';
  document.getElementById('usr-pw').value='';
  document.getElementById('usr-pw').placeholder='Mínimo 8 caracteres, com letra e número';
  const pf=document.getElementById('usr-pf'); if(pf)pf.value='operacional';
  // Limpa TODAS as permissões (usuário novo começa sem nada marcado)
  const modCrud=['frota','manut','cts','meds','vend','estq','desp','fin','pneus','resultado','clientes','mob','func','prej','sm','sist','cpagar','creceber','prop','tratativas'];
  const allPerms=['dash','whatsapp','adm','custo','preco','desc','estq-edit','venda-eq','pneu-edit','rel','rel-fin','rel-os','rel-frota','rel-resultado','rel-estq','rel-cpagar','rel-creceber','rel-fin-imp','rel-os-imp','rel-frota-imp','rel-resultado-imp','rel-estq-imp','rel-cpagar-imp','rel-creceber-imp','contas-dia','aniversarios','confirma-ajuda','motivacao','kpi-fin','contas-banco','backup-manual','exportar','ajuda-custo','ver-auditoria','ver-resultado-placa','gerenciar-usuarios','enviar-email','seguro','doc-veiculo'];
  modCrud.forEach(m=>{allPerms.push(m);allPerms.push(m+'-criar');allPerms.push(m+'-editar');allPerms.push(m+'-excluir');});
  allPerms.forEach(p=>{const el=document.getElementById('pr-'+p);if(!el)return;if(el.type==='checkbox')el.checked=false;else el.classList.remove('on');});
  const t=document.querySelector('#m-usr .mt2'); if(t)t.textContent='👤 Novo Usuário';
  openM('m-usr');
}

async function saveUsr(){
  const nm=document.getElementById('usr-nm').value.trim();
  const lg=document.getElementById('usr-lg').value.trim().toLowerCase();
  const pw=document.getElementById('usr-pw').value;
  const pf=document.getElementById('usr-pf').value;
  const eid=document.getElementById('usr-eid').value;
  if(!nm){toast('Informe o nome do usuário','er');return;}
  if(!lg){toast('Informe o login','er');return;}
  if(!eid&&!pw){toast('Informe a senha para novo usuário','er');return;}
  // Check duplicate login
  const dupLogin=D.usuarios.find(u=>u.lg===lg&&u.id!==eid);
  if(dupLogin){toast('Este login já está em uso','er');return;}
  const perms={};
  // Lista completa: módulos base + ações CRUD + permissões específicas + relatórios
  const modCrud=['frota','manut','cts','meds','vend','estq','desp','fin','pneus','resultado','clientes','mob','func','prej','sm','sist','cpagar','creceber','prop','tratativas'];
  const allPerms=['dash','whatsapp','adm','custo','preco','desc','estq-edit','venda-eq','pneu-edit','rel',
    'rel-fin','rel-os','rel-frota','rel-resultado','rel-estq','rel-cpagar','rel-creceber',
    'rel-fin-imp','rel-os-imp','rel-frota-imp','rel-resultado-imp','rel-estq-imp','rel-cpagar-imp','rel-creceber-imp',
    'contas-dia','aniversarios','confirma-ajuda','motivacao','kpi-fin','contas-banco','backup-manual','exportar','ajuda-custo','ver-auditoria','ver-resultado-placa','gerenciar-usuarios','enviar-email','seguro','doc-veiculo'];
  // Add CRUD variants
  modCrud.forEach(m=>{
    allPerms.push(m);
    allPerms.push(m+'-criar');
    allPerms.push(m+'-editar');
    allPerms.push(m+'-excluir');
  });
  allPerms.forEach(p=>{
    const el=document.getElementById('pr-'+p);
    if(!el){perms[p]=false;return;}
    // Checkbox usa .checked, toggle usa classe .on
    if(el.type==='checkbox') perms[p]=el.checked;
    else perms[p]=el.classList.contains('on');
  });
  // Está conectado (online) como admin no servidor?
  const online = syncAtivo && authToken && !String(authToken).startsWith('local_');

  // 1) Sincroniza no SERVIDOR (tabela de login mh3_usuarios) — é isso que faz logar em qualquer PC
  if(online){
    const okServer = await syncUsuarioServidor({nm,lg,pw,pf,perms});
    if(!okServer) return; // servidor recusou (ex: senha fraca) — mensagem já mostrada, não salva
  }

  // 2) Salva localmente (para exibir na tela e funcionar offline)
  if(eid){
    const idx=D.usuarios.findIndex(u=>u.id===eid);
    if(idx>-1){
      D.usuarios[idx]={...D.usuarios[idx],nm,lg,pf,perms};
      if(pw) D.usuarios[idx].pw=pw;
    }
  }else{
    D.usuarios.push({id:uid(),nm,lg,pw,pf,perms});
  }
  document.getElementById('usr-eid').value='';
  document.getElementById('usr-pw').placeholder='••••••••';
  document.querySelector('#m-usr .mt2').textContent='👤 Usuário';
  D.config.usuarios = D.usuarios; // espelho local
  try{normalizarUsuarios();}catch(e){}
  sv();closeM('m-usr');rdUsr();

  if(online) toast(eid?'Usuário atualizado e sincronizado! Já entra em qualquer PC.':'Usuário criado e sincronizado! Já entra em qualquer PC.','ok');
  else toast('Salvo neste PC. Entre como admin conectado (online) para validar em outros PCs.','er');
}

// Cadastra/atualiza o usuário no servidor (tabela mh3_usuarios), via usuario_salvar.
// Procura pelo login para reaproveitar o mesmo ID (cria ou atualiza corretamente).
async function syncUsuarioServidor(u){
  try{
    let serverId='';
    try{
      const lr=await fetch('api.php?action=usuarios_listar&token='+encodeURIComponent(authToken),{headers:{'X-Token':authToken}});
      const lj=await lr.json();
      if(lj && lj.ok && lj.dados){
        const ex=lj.dados.find(x=>(x.login||'').toLowerCase()===u.lg.toLowerCase());
        if(ex) serverId=ex.id;
      }
    }catch(e){}
    const body={id:serverId, nome:u.nm, login:u.lg, perfil:u.pf, permissoes:u.perms};
    if(u.pw) body.senha=u.pw; // só envia senha se foi informada (em edição pode ficar vazia)
    const sr=await fetch('api.php?action=usuario_salvar&token='+encodeURIComponent(authToken),{
      method:'POST', headers:{'Content-Type':'application/json','X-Token':authToken},
      body: JSON.stringify(body)
    });
    const sj=await sr.json();
    if(!sj || !sj.ok){ toast((sj&&sj.msg)||'Erro ao salvar usuário no servidor.','er'); return false; }
    return true;
  }catch(e){ toast('Sem conexão com o servidor para salvar o usuário. Tente novamente.','er'); return false; }
}
function delUsr(id){reqSenha(()=>{if(!confirm('Excluir?'))return;
  const u=D.usuarios.find(x=>x.id===id);
  D.usuarios=D.usuarios.filter(x=>x.id!==id);
  D.config.usuarios=D.usuarios;
  sv();rdUsr();
  // Desativa no servidor (para não logar mais em nenhum PC)
  if(u && syncAtivo && authToken && !String(authToken).startsWith('local_')){
    (async()=>{try{
      const lr=await fetch('api.php?action=usuarios_listar&token='+encodeURIComponent(authToken),{headers:{'X-Token':authToken}});
      const lj=await lr.json();
      if(lj&&lj.ok&&lj.dados){const ex=lj.dados.find(x=>(x.login||'').toLowerCase()===(u.lg||'').toLowerCase());
        if(ex)await fetch('api.php?action=usuario_deletar&token='+encodeURIComponent(authToken),{method:'POST',headers:{'Content-Type':'application/json','X-Token':authToken},body:JSON.stringify({id:ex.id})});}
    }catch(e){}})();
  }
});}

