function abrirImportKmHr(){
  var p=document.getElementById('imp-kmhr-paste'); if(p)p.value='';
  var pv=document.getElementById('imp-kmhr-preview'); if(pv)pv.innerHTML='';
  var bt=document.getElementById('imp-kmhr-btn'); if(bt)bt.style.display='none';
  var ck=document.getElementById('imp-kmhr-km'); if(ck)ck.checked=true;
  var ch=document.getElementById('imp-kmhr-hr'); if(ch)ch.checked=true;
  window._impKmHrLinhas=[];
  if(typeof openM==='function')openM('m-imp-kmhr');
}
function processarImportKmHr(){
  var txt=(document.getElementById('imp-kmhr-paste')||{}).value||'';
  var linhas=(typeof parseCSV==='function')?parseCSV(txt):[];
  var pv=document.getElementById('imp-kmhr-preview');
  var bt=document.getElementById('imp-kmhr-btn');
  if(!linhas.length){if(typeof toast==='function')toast('Cole a planilha primeiro.','er');return;}
  var impKm=document.getElementById('imp-kmhr-km').checked;
  var impHr=document.getElementById('imp-kmhr-hr').checked;
  if(!impKm&&!impHr){if(typeof toast==='function')toast('Marque pelo menos KM ou Horímetro.','er');return;}
  var header=linhas[0].map(function(h){return (h||'').toLowerCase();});
  var idxPlaca=-1,idxKm=-1,idxHr=-1;
  header.forEach(function(h,i){
    if(idxPlaca<0&&h.indexOf('placa')>=0)idxPlaca=i;
    if(idxHr<0&&h.indexOf('hori')>=0)idxHr=i;
    if(idxKm<0&&h.indexOf('km')>=0)idxKm=i;
  });
  var temHeader=idxPlaca>=0;
  if(!temHeader){idxPlaca=0;idxKm=1;idxHr=2;}
  var soNum=function(s){return parseInt(String(s||'').replace(/\./g,'').replace(/[^0-9]/g,''))||0;};
  var dados=temHeader?linhas.slice(1):linhas;
  var np=function(p){return (typeof _normPlacaImp==='function')?_normPlacaImp(p):String(p||'').toUpperCase().replace(/[^A-Z0-9]/g,'');};
  var res=[];
  dados.forEach(function(c){
    var placaCSV=(c[idxPlaca]||'').trim();
    if(!placaCSV)return;
    var npc=np(placaCSV);
    var eq=(D.equips||[]).find(function(e){return np(e.placa||e.pl)===npc;});
    var kmNovo=(impKm&&idxKm>=0)?soNum(c[idxKm]):null;
    var hrNovo=(impHr&&idxHr>=0)?soNum(c[idxHr]):null;
    res.push({placaCSV:placaCSV,achou:!!eq,eqId:eq?eq.id:'',placaSis:eq?(eq.placa||eq.pl||''):'',
              kmAtual:eq?(eq.km||'0'):'',hrAtual:eq?(eq.hr||'0'):'',kmNovo:kmNovo,hrNovo:hrNovo});
  });
  window._impKmHrLinhas=res;
  window._impKmHrFlags={km:impKm,hr:impHr};
  var achados=res.filter(function(l){return l.achou;}).length;
  var escH=function(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');};
  if(!res.length){pv.innerHTML='<p class="empty">Nenhuma linha válida.</p>';bt.style.display='none';return;}
  var h='<div style="font-size:12px;margin-bottom:6px"><b>'+achados+'</b> de <b>'+res.length+'</b> placa(s) encontrada(s) na frota.';
  if(achados<res.length)h+=' <span style="color:var(--rd)">As não encontradas serão ignoradas.</span>';
  h+='</div>';
  h+='<table style="width:100%;border-collapse:collapse;font-size:11px"><thead><tr style="background:var(--cd2)"><th style="padding:5px;text-align:left">Placa</th>';
  if(impKm)h+='<th style="padding:5px;text-align:left">KM: atual &rarr; novo</th>';
  if(impHr)h+='<th style="padding:5px;text-align:left">Horímetro: atual &rarr; novo</th>';
  h+='<th style="padding:5px;text-align:left">Situação</th></tr></thead><tbody>';
  res.forEach(function(l){
    var op=l.achou?'':'opacity:.5';
    h+='<tr style="border-bottom:1px solid var(--br);'+op+'"><td style="padding:5px">'+escH(l.placaCSV)+'</td>';
    if(impKm)h+='<td style="padding:5px">'+(l.achou?(escH(l.kmAtual||'0')+' &rarr; <b>'+escH(l.kmNovo)+'</b>'):'—')+'</td>';
    if(impHr)h+='<td style="padding:5px">'+(l.achou?(escH(l.hrAtual||'0')+' &rarr; <b>'+escH(l.hrNovo)+'</b>'):'—')+'</td>';
    h+='<td style="padding:5px">'+(l.achou?'<span style="color:var(--gr)">✓ encontrada</span>':'<span style="color:var(--rd)">✗ não cadastrada</span>')+'</td></tr>';
  });
  h+='</tbody></table>';
  pv.innerHTML=h;
  bt.style.display=achados?'':'none';
}
function confirmarImportKmHr(){
  var linhas=window._impKmHrLinhas||[];
  var flags=window._impKmHrFlags||{};
  var ok=linhas.filter(function(l){return l.achou;});
  if(!ok.length){if(typeof toast==='function')toast('Nenhuma placa bateu com a frota.','er');return;}
  var hoje=(typeof today==='function')?today():new Date().toISOString().slice(0,10);
  var n=0;
  ok.forEach(function(l){
    var eq=(D.equips||[]).find(function(e){return e.id===l.eqId;});
    if(!eq)return;
    var mudou=false;
    if(flags.km&&l.kmNovo!=null){eq.km=String(l.kmNovo);mudou=true;}
    if(flags.hr&&l.hrNovo!=null){eq.hr=String(l.hrNovo);mudou=true;}
    if(mudou){eq.kmDt=hoje;n++;}
  });
  if(typeof auditar==='function')auditar('IMPORTACAO','frota','Atualização em massa de KM/Horímetro: '+n+' veículo(s)');
  if(typeof sv==='function')sv();
  if(typeof toast==='function')toast(n+' veículo(s) atualizado(s)! Os valores antigos errados deixam de atrapalhar.','ok');
  if(typeof closeM==='function')closeM('m-imp-kmhr');
  if(typeof rdFrota==='function')rdFrota();
}

function importarFrotaPlanilha(){
  if(!confirm('Importar '+FROTA_PLANILHA.length+' veículos da planilha?\n\nVeículos com placa que já existe serão ignorados (não duplica). Os demais entram como "disponível" para você completar os dados depois.'))return;
  let add=0, pulou=0;
  FROTA_PLANILHA.forEach(v=>{
    const pl=(v.pl||'').toUpperCase().trim();
    // Evita duplicar: por placa (quando tem) ou por marca+modelo (quando sem placa)
    if(pl){
      if(D.equips.some(e=>((e.pl||e.placa||'').toUpperCase().trim())===pl)){pulou++;return;}
    } else {
      const chave=((v.mk||'')+' '+(v.mo||'')).toUpperCase().trim();
      if(D.equips.some(e=>!e.pl&&((e.mk||'')+' '+(e.mo||'')).toUpperCase().trim()===chave)){pulou++;return;}
    }
    D.equips.push({
      id:uid(),
      pl:pl, placa:pl,
      mk:v.mk||'', mo:v.mo||'', an:v.an||'',
      ch:v.ch||'', rv:v.rv||'', crv:v.crv||'',
      st:'disponivel', cond:'usado',
      ob:'Importado da planilha FROTA_MH3 08/06'
    });
    add++;
  });
  auditar('IMPORTACAO','frota','Importação da planilha: '+add+' veículos adicionados, '+pulou+' ignorados (já existiam)');
  sv();rdFrota();
  toast(add+' veículos importados! '+(pulou?pulou+' ignorados (já existiam).':''),'ok');
}

// ---- INVESTIMENTOS (consórcios e bens em pagamento) ----
function addInvestimento(){
  const desc=document.getElementById('inv-desc').value.trim();
  if(!desc){toast('Informe a descrição','er');return;}
  const inv={
    id:uid(),desc,
    tipo:document.getElementById('inv-tipo').value,
    adm:document.getElementById('inv-adm').value.trim(),
    valorCarta:parseFloat(document.getElementById('inv-valor-carta').value)||0,
    nparc:parseInt(document.getElementById('inv-nparc').value)||0,
    parcpg:parseInt(document.getElementById('inv-parcpg').value)||0,
    vparc:parseFloat(document.getElementById('inv-vparc').value)||0,
    dt:document.getElementById('inv-dt').value,
    diaVenc:parseInt(document.getElementById('inv-dia-venc').value)||10,
    obs:document.getElementById('inv-obs').value.trim(),
    status:'andamento',reajustes:[]
  };
  D.investimentos.push(inv);
  // Lança TODAS as parcelas restantes no Contas a Pagar (igual financiamento de frota)
  const lancadas=lancarParcelasInvestimento(inv);
  auditar('CRIACAO','financeiro','Investimento cadastrado: '+desc+' ('+lancadas+' parcelas no Contas a Pagar)');
  ['inv-desc','inv-adm','inv-valor-carta','inv-nparc','inv-parcpg','inv-vparc','inv-obs'].forEach(i=>{const el=document.getElementById(i);if(el)el.value='';});
  sv();rdInvestimento();
  toast('Investimento cadastrado! '+lancadas+' parcelas lançadas no Contas a Pagar.','ok');
}

function lancarParcelasInvestimento(inv){
  // Lança as parcelas RESTANTES (das já pagas+1 até o total) no Contas a Pagar, uma por mês
  const total=inv.nparc||0;
  const jaPagas=inv.parcpg||0;
  if(total<=jaPagas) return 0;
  // Base: data de início é o vencimento da 1ª parcela. Parcela N vence em início + (N-1) meses.
  const base=inv.dt?new Date(inv.dt+'T12:00'):new Date();
  const dia=inv.diaVenc||base.getDate();
  let count=0;
  for(let i=jaPagas+1;i<=total;i++){
    const dt=new Date(base);
    dt.setMonth(dt.getMonth()+(i-1));
    dt.setDate(Math.min(dia, new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate()));
    D.despesas.push({
      id:uid(),
      desc:'INVESTIMENTO — '+inv.desc+' (parcela '+i+'/'+total+')',
      cat:'Investimento',
      vl:inv.vparc||0,
      dt:new Date().toISOString().substring(0,10),
      vc:dt.toISOString().substring(0,10),
      st:'pendente',fluxo:'sim',cp:'sim',
      forn:inv.adm||inv.desc,
      ob:'Consórcio/Investimento'+(inv.obs?' — '+inv.obs:''),
      origemInv:inv.id,
      parcela:i,totalParc:total,
      travada:true
    });
    count++;
  }
  return count;
}

function statusInvLabel(s){return s==='contemplado'?'Contemplado':s==='utilizado'?'Na Frota':s==='quitado'?'Quitado':'Em Andamento';}
/* ===== MÓDULO SEGURO (apólices por placa) ===== */
function _segNorm(p){return String(p||'').toUpperCase().replace(/[^A-Z0-9]/g,'');}
function _segAtivoVeic(placa){
  var pl=_segNorm(placa); if(!pl) return null;
  var c=(D.seguros||[]).filter(function(s){return (s.placas||[]).some(function(p){return _segNorm(p)===pl;});});
  if(!c.length) return null;
  c.sort(function(a,b){return (b.venc||'').localeCompare(a.venc||'');});
  return c[0];
}
function _segStatus(venc){
  if(!venc) return {txt:'sem vencimento',sty:'background:#e5e7eb;color:#374151',dias:null};
  var h=new Date();h.setHours(0,0,0,0);
  var d=new Date(venc+'T00:00:00');
  var dias=Math.round((d-h)/86400000);
  if(dias<0) return {txt:'VENCIDO há '+(-dias)+'d',sty:'background:#fee2e2;color:#b91c1c',dias:dias};
  if(dias<=15) return {txt:'vence em '+dias+'d',sty:'background:#fef3c7;color:#b45309',dias:dias};
  return {txt:'em dia',sty:'background:#dcfce7;color:#15803d',dias:dias};
}
function _segBadge(venc){var st=_segStatus(venc);return '<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;'+st.sty+'">'+st.txt+'</span>';}
function _seguroInfoHtml(placa){
  var s=_segAtivoVeic(placa);
  if(!s) return '<span style="color:#C8102E;font-weight:700">⚠️ SEM SEGURO</span> — marque esta placa numa apólice na aba Seguro.';
  return '<b>'+escH(s.seguradora||'-')+'</b>'+(s.apolice?(' · Apólice '+escH(s.apolice)):'')+' · vence '+fmtData(s.venc)+'<br>'+_segBadge(s.venc);
}
function rdSeguro(){
  var tb=document.getElementById('seg-tb'); if(!tb) return;
  var lista=(D.seguros||[]).slice().sort(function(a,b){return (a.venc||'').localeCompare(b.venc||'');});
  tb.innerHTML = !lista.length
    ? '<tr><td colspan="6" class="empty">Nenhuma apólice cadastrada. Clique em "+ Apólice".</td></tr>'
    : lista.map(function(s){
        var placas=(s.placas||[]); var pt=placas.join(', ')||'—';
        return '<tr>'+
          '<td><b>'+escH(s.seguradora||'-')+'</b></td>'+
          '<td style="font-size:11px">'+escH(s.apolice||'-')+'</td>'+
          '<td style="font-size:11px">'+(s.inicio?fmtData(s.inicio)+' a ':'')+'<b>'+fmtData(s.venc)+'</b><br>'+_segBadge(s.venc)+'</td>'+
          '<td style="font-size:11px">'+(s.valor?fmt(s.valor):'-')+'</td>'+
          '<td style="font-size:10px;color:var(--mt)" title="'+escH(pt)+'"><b>'+placas.length+'</b> placa(s)<br>'+escH(pt.length>50?pt.slice(0,50)+'…':pt)+'</td>'+
          '<td style="white-space:nowrap"><button class="btn bw btn-xs" onclick="editSeguro(\''+s.id+'\')">✏</button> <button class="btn bd btn-xs" onclick="delSeguro(\''+s.id+'\')">×</button></td>'+
        '</tr>';
      }).join('');
  var cob={}; (D.seguros||[]).forEach(function(s){(s.placas||[]).forEach(function(p){cob[_segNorm(p)]=1;});});
  var sem=(D.equips||[]).filter(function(e){return e.st!=='vendido' && !cob[_segNorm(e.placa)];});
  var ss=document.getElementById('seg-semseguro');
  if(ss){ ss.innerHTML = !sem.length
    ? '<div style="color:#15803d;font-size:12px">✅ Todos os veículos ativos estão em alguma apólice.</div>'
    : '<div style="font-weight:700;color:#C8102E;font-size:12px;margin-bottom:6px">⚠️ '+sem.length+' veículo(s) SEM SEGURO:</div><div style="display:flex;flex-wrap:wrap;gap:5px">'+sem.map(function(e){return '<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:10px;font-weight:700;background:#fee2e2;color:#b91c1c">'+escH(e.placa||'?')+' '+escH(e.mo||'')+'</span>';}).join('')+'</div>';
  }
  var al=document.getElementById('seg-alertas');
  if(al){
    var av=lista.filter(function(s){var st=_segStatus(s.venc);return st.dias!==null && st.dias<=15;});
    if(!av.length){ al.style.display='none'; al.innerHTML=''; }
    else { al.style.display='block'; al.innerHTML='<b>🔔 Seguros a vencer / vencidos:</b>'+av.map(function(s){var st=_segStatus(s.venc);return '<div style="margin-top:3px">• <b>'+escH(s.seguradora||'-')+'</b> (apólice '+escH(s.apolice||'-')+') — '+st.txt+'. Gere a renovação ou tire as placas.</div>';}).join(''); }
  }
}
function openSeguro(){ window._segEdit=null; _segPreencheModal({}); openM('m-seguro'); }
function editSeguro(id){ var s=(D.seguros||[]).find(function(x){return x.id===id;}); if(!s)return; window._segEdit=id; _segPreencheModal(s); openM('m-seguro'); }
function _segPreencheModal(s){
  s=s||{};
  var set=function(id,v){var el=document.getElementById(id);if(el)el.value=(v===undefined||v===null)?'':v;};
  set('seg-seguradora',s.seguradora); set('seg-apolice',s.apolice);
  set('seg-inicio',s.inicio); set('seg-venc',s.venc);
  set('seg-valor', s.valor?(''+s.valor).replace('.',','):''); set('seg-obs',s.obs);
  var ttl=document.getElementById('seg-mtitle'); if(ttl) ttl.textContent=(window._segEdit?'✏️ Editar Apólice':'🛡️ Nova Apólice');
  var box=document.getElementById('seg-placas');
  if(box){
    var sel=(s.placas||[]).map(_segNorm);
    var eqs=(D.equips||[]).filter(function(e){return e.st!=='vendido';}).slice().sort(function(a,b){return (a.placa||'').localeCompare(b.placa||'');});
    box.innerHTML = eqs.length ? eqs.map(function(e){
      var ck=sel.indexOf(_segNorm(e.placa))>=0?'checked':'';
      return '<label style="display:flex;align-items:center;gap:6px;padding:4px 6px;font-size:12px;cursor:pointer"><input type="checkbox" class="seg-pl-chk" value="'+escH(e.placa||'')+'" '+ck+'> <b>'+escH(e.placa||'?')+'</b> <span style="color:var(--mt)">'+escH((e.mk||'')+' '+(e.mo||''))+'</span></label>';
    }).join('') : '<div style="color:var(--mt);font-size:12px">Nenhum veículo cadastrado.</div>';
  }
  setTimeout(function(){var b=document.getElementById('seg-busca-placa'); if(b)b.value='';},30);
}
function _segFiltraPlacas(q){ q=(q||'').toLowerCase(); document.querySelectorAll('#seg-placas label').forEach(function(l){ l.style.display=l.textContent.toLowerCase().indexOf(q)>=0?'flex':'none'; }); }
function _segMarcarTodas(v){ document.querySelectorAll('#seg-placas .seg-pl-chk').forEach(function(c){ var lab=c.closest('label'); if(!lab||lab.style.display!=='none') c.checked=v; }); }
function saveSeguro(){
  var g=function(id){var el=document.getElementById(id);return el?(el.value||'').trim():'';};
  var seguradora=g('seg-seguradora'), venc=g('seg-venc');
  if(!seguradora){ if(typeof toast==='function')toast('Informe a seguradora.','er'); return; }
  if(!venc){ if(typeof toast==='function')toast('Informe o vencimento.','er'); return; }
  var placas=[]; document.querySelectorAll('#seg-placas .seg-pl-chk:checked').forEach(function(c){ placas.push(c.value); });
  var valNum = (typeof _parseValorBR==='function') ? _parseValorBR(g('seg-valor')) : (parseFloat((g('seg-valor')||'0').replace(/\./g,'').replace(',','.'))||0);
  var obj={ seguradora:seguradora, apolice:g('seg-apolice'), inicio:g('seg-inicio'), venc:venc, valor:valNum, obs:g('seg-obs'), placas:placas };
  if(window._segEdit){
    var i=(D.seguros||[]).findIndex(function(x){return x.id===window._segEdit;});
    if(i>=0){ obj.id=window._segEdit; D.seguros[i]={...D.seguros[i],...obj}; }
    if(typeof auditar==='function') auditar('ALTERACAO','seguro','Editou apólice '+seguradora+' ('+placas.length+' placas), venc '+venc);
  } else {
    obj.id='seg_'+Date.now()+'_'+Math.floor(Math.random()*999);
    D.seguros=D.seguros||[]; D.seguros.push(obj);
    if(typeof auditar==='function') auditar('CRIACAO','seguro','Nova apólice '+seguradora+' ('+placas.length+' placas), venc '+venc);
  }
  if(typeof sv==='function') sv();
  if(typeof closeM==='function') closeM('m-seguro');
  rdSeguro();
  if(typeof toast==='function') toast('Apólice salva.','ok');
}
function delSeguro(id){
  if(typeof ehAdminAtual==='function' && !ehAdminAtual()){ if(typeof toast==='function')toast('Apenas o administrador pode excluir apólices.','er'); return; }
  var s=(D.seguros||[]).find(function(x){return x.id===id;}); if(!s)return;
  if(!confirm('Excluir a apólice da '+(s.seguradora||'?')+'?\nAs placas dela ficarão SEM SEGURO.')) return;
  reqSenha(function(){
    D.seguros=(D.seguros||[]).filter(function(x){return x.id!==id;});
    if(typeof auditarExclusao==='function') auditarExclusao('seguro','Excluiu apólice '+(s.seguradora||'?'));
    if(typeof sv==='function') sv();
    rdSeguro();
    if(typeof toast==='function') toast('Apólice excluída.','ok');
  });
}
function imprimirSeguro(){ if(typeof imprimirComOpcoes==='function') imprimirComOpcoes('Seguro — Apólices e Vencimentos'); else window.print(); }

function rdInvestimento(){
  const dtEl=document.getElementById('inv-dt');
  if(dtEl&&!dtEl.value)dtEl.value=new Date().toISOString().substring(0,10);
  const tb=document.getElementById('inv-tb');
  if(!tb)return;
  const lista=D.investimentos||[];
  let totalPago=0;
  tb.innerHTML=lista.length?lista.map(inv=>{
    const pagoAcum=(inv.parcpg||0)*(inv.vparc||0);
    totalPago+=pagoAcum;
    const faltam=Math.max(0,(inv.nparc||0)-(inv.parcpg||0));
    const badge=inv.status==='utilizado'?'b-gn':inv.status==='contemplado'?'b-cy':inv.status==='quitado'?'b-pu':'b-yw';
    return `<tr>
      <td><b>${inv.desc}</b>${inv.adm?'<br><span style="font-size:10px;color:var(--mt)">'+inv.adm+'</span>':''}</td>
      <td style="font-size:11px">${inv.tipo}</td>
      <td>${fmt(inv.valorCarta)}</td>
      <td style="font-size:11px">${inv.parcpg||0}/${inv.nparc||0}${faltam>0?'<br><span style="color:var(--red);font-size:10px">faltam '+faltam+'</span>':''}</td>
      <td>${fmt(inv.vparc)}</td>
      <td style="color:var(--bl);font-weight:600">${fmt(pagoAcum)}</td>
      <td><span class="badge ${badge}">${statusInvLabel(inv.status)}</span></td>
      <td style="white-space:nowrap">
        ${inv.status!=='utilizado'?`<button class="btn bw btn-xs" onclick="reajusteInv('${inv.id}')" title="Reajustar parcela (atualiza as futuras no Contas a Pagar)">📊 Reajuste</button>
        <button class="btn bb btn-xs" onclick="enviarInvFrota('${inv.id}')" title="Contemplado: enviar para a Frota">🚚 Frota</button>`:''}
        <button class="btn bd btn-xs" onclick="delInvestimento('${inv.id}')" title="Excluir">×</button>
      </td>
    </tr>`;
  }).join(''):'<tr><td colspan="8" class="empty">Nenhum investimento cadastrado</td></tr>';
  const tEl=document.getElementById('inv-total');if(tEl)tEl.textContent=fmt(totalPago);
}
function pagarParcelaInv(id){
  const inv=D.investimentos.find(x=>x.id===id);
  if(!inv)return;
  if((inv.parcpg||0)>=(inv.nparc||0)){toast('Todas as parcelas já foram pagas','er');return;}
  const hoje=new Date();
  const venc=new Date(hoje.getFullYear(),hoje.getMonth(),inv.diaVenc||10).toISOString().substring(0,10);
  inv.parcpg=(inv.parcpg||0)+1;
  // Lança em Contas a Pagar
  D.despesas.push({
    id:uid(),desc:'INVESTIMENTO — '+inv.desc+' (parcela '+inv.parcpg+'/'+inv.nparc+')',
    cat:'Investimento',vl:inv.vparc,dt:venc,vc:venc,st:'pendente',fluxo:'sim',cp:'sim',
    forn:inv.adm||inv.desc,ob:'Consórcio/Investimento'+(inv.obs?' — '+inv.obs:''),origemInv:id
  });
  if(inv.parcpg>=inv.nparc)inv.status='quitado';
  auditar('CRIACAO','financeiro','Parcela investimento paga: '+inv.desc+' ('+inv.parcpg+'/'+inv.nparc+') → Contas a Pagar');
  sv();rdInvestimento();
  toast('Parcela '+inv.parcpg+'/'+inv.nparc+' lançada em Contas a Pagar!','ok');
}
function reajusteInv(id){
  const inv=D.investimentos.find(x=>x.id===id);
  if(!inv)return;
  const novo=prompt('Reajuste de '+inv.desc+'\nValor atual da parcela: '+fmt(inv.vparc)+'\n\nNovo valor da parcela (R$):');
  if(novo===null)return;
  const nv=parseFloat(novo.replace(',','.'))||0;
  if(nv<=0){toast('Valor inválido','er');return;}
  const mes=new Date().toISOString().substring(0,7);
  inv.reajustes=inv.reajustes||[];
  inv.reajustes.push({mes,de:inv.vparc,para:nv});
  inv.vparc=nv;
  // Atualiza as parcelas FUTURAS ainda pendentes no Contas a Pagar com o novo valor
  let atualizadas=0;
  D.despesas.forEach(d=>{if(d.origemInv===inv.id && d.st!=='pago'){d.vl=nv;atualizadas++;}});
  auditar('ALTERACAO','financeiro','Reajuste investimento '+inv.desc+': '+fmt(inv.reajustes[inv.reajustes.length-1].de)+' → '+fmt(nv)+' ('+atualizadas+' parcelas pendentes atualizadas)');
  sv();rdInvestimento();
  toast('Reajuste aplicado! '+atualizadas+' parcelas pendentes atualizadas para '+fmt(nv),'ok');
}
function enviarInvFrota(id){
  const inv=D.investimentos.find(x=>x.id===id);
  if(!inv)return;
  if(!confirm('Enviar "'+inv.desc+'" para a Frota?\n\nSerá criado um veículo/equipamento com os dados do investimento ('+inv.parcpg+' parcelas pagas, '+fmt(inv.parcpg*inv.vparc)+' investido).'))return;
  // Cria entrada na frota vinculada ao investimento
  const novoEq={
    id:uid(),
    pl:'(definir placa)',placa:'(definir placa)',
    mk:inv.desc,mo:'',an:'',ch:'',
    st:'disponivel',cond:'novo',
    situ:inv.tipo==='consorcio'?'consorcio':'financiado',
    vaql:inv.valorCarta||0,
    daql:new Date().toISOString().substring(0,10),
    nparc:inv.nparc||0,parcpg:inv.parcpg||0,
    vparc:inv.vparc||0,banco:inv.adm||'',
    origemInvestimento:id,
    ob:'Originado do investimento: '+inv.desc+' | '+inv.parcpg+' parcelas pagas | Investido: '+fmt(inv.parcpg*inv.vparc)+(inv.obs?' | '+inv.obs:'')
  };
  D.equips.push(novoEq);
  inv.status='utilizado';inv.eqId=novoEq.id;
  auditar('CRIACAO','frota','Investimento contemplado enviado à Frota: '+inv.desc);
  sv();rdInvestimento();
  toast('Enviado para a Frota! Edite o veículo para definir a placa e completar os dados.','ok');
  setTimeout(()=>{if(confirm('Ir para a Frota agora para completar o cadastro?'))go('frota');},800);
}
function delInvestimento(id){
  reqSenha(()=>{
    const inv=D.investimentos.find(x=>x.id===id);
    if(!inv)return;
    if(!confirm('Excluir o investimento "'+inv.desc+'"?'))return;
    D.investimentos=D.investimentos.filter(x=>x.id!==id);
    // Remove as parcelas pendentes deste investimento do Contas a Pagar (mantém as já pagas)
    const antes=D.despesas.length;
    D.despesas=D.despesas.filter(d=>!(d.origemInv===id && d.st!=='pago'));
    const removidas=antes-D.despesas.length;
    auditar('EXCLUSAO','financeiro','Investimento excluído: '+inv.desc+' ('+removidas+' parcelas pendentes removidas)');
    sv();rdInvestimento();
    toast('Investimento excluído ('+removidas+' parcelas pendentes removidas do Contas a Pagar)','ok');
  });
}

// ---- CONTAS BANCÁRIAS MH3 (item 2) ----
function openContaBanco(){
  document.getElementById('cb-id').value='';
  document.getElementById('cb-mtitle').textContent='🏦 Nova Conta Bancária';
  ['cb-nome','cb-banco','cb-ag','cb-conta','cb-saldo','cb-saldo-pa'].forEach(i=>document.getElementById(i).value='');
  document.getElementById('cb-tipo').value='corrente';
  document.getElementById('cb-fluxo').checked=true;
  // Conta nova: pode digitar o saldo inicial
  var _s1=document.getElementById('cb-saldo'),_s2=document.getElementById('cb-saldo-pa');
  if(_s1){_s1.readOnly=false;_s1.style.opacity='1';_s1.title='';}
  if(_s2){_s2.readOnly=false;_s2.style.opacity='1';_s2.title='';}
  openM('m-conta-banco');
}
function saveContaBanco(){
  const id=document.getElementById('cb-id').value;
  const nome=document.getElementById('cb-nome').value.trim();
  if(!nome){toast('Informe o nome da conta','er');return;}
  const data={
    nome,banco:document.getElementById('cb-banco').value.trim(),
    ag:document.getElementById('cb-ag').value.trim(),
    conta:document.getElementById('cb-conta').value.trim(),
    tipo:document.getElementById('cb-tipo').value,
    noFluxo:document.getElementById('cb-fluxo').checked
  };
  if(id){
    // EDIÇÃO: NÃO mexe no saldo aqui — o saldo só muda pelo botão "Acerto de Saldo".
    const idx=D.contasBanco.findIndex(c=>c.id===id);
    if(idx>-1)D.contasBanco[idx]={...D.contasBanco[idx],...data};
    auditar('ALTERACAO','financeiro','Conta bancária editada (saldo não alterado aqui): '+nome);
  }else{
    // CONTA NOVA: aqui sim define o saldo inicial.
    data.saldo=parseFloat(document.getElementById('cb-saldo').value)||0;
    data.saldoPA=parseFloat(document.getElementById('cb-saldo-pa').value)||0;
    data.id=uid();D.contasBanco.push(data);
    auditar('CRIACAO','financeiro','Conta bancária cadastrada: '+nome);
  }
  sv();closeM('m-conta-banco');rdContasBanco();if(typeof rdFluxo==='function')rdFluxo();
  toast('Conta bancária salva!','ok');
}
function editContaBanco(id){if(_bloqEditar('fin'))return;
  const c=D.contasBanco.find(x=>x.id===id);
  if(!c)return;
  document.getElementById('cb-id').value=id;
  document.getElementById('cb-mtitle').textContent='✏️ Editar Conta';
  document.getElementById('cb-nome').value=c.nome||'';
  document.getElementById('cb-banco').value=c.banco||'';
  document.getElementById('cb-ag').value=c.ag||'';
  document.getElementById('cb-conta').value=c.conta||'';
  document.getElementById('cb-tipo').value=c.tipo||'corrente';
  document.getElementById('cb-saldo').value=c.saldo||'';
  document.getElementById('cb-saldo-pa').value=c.saldoPA||'';
  document.getElementById('cb-fluxo').checked=c.noFluxo!==false;
  // Edição: saldo fica TRAVADO aqui — só muda pelo botão "⚖️ Acerto de Saldo"
  var _s1=document.getElementById('cb-saldo'),_s2=document.getElementById('cb-saldo-pa');
  if(_s1){_s1.readOnly=true;_s1.style.opacity='.6';_s1.title='Para mudar o saldo, use o botão Acerto de Saldo';}
  if(_s2){_s2.readOnly=true;_s2.style.opacity='.6';_s2.title='Para mudar o saldo, use o botão Acerto de Saldo';}
  openM('m-conta-banco');
}
function delContaBanco(id){
  reqSenha(()=>{
    const c=D.contasBanco.find(x=>x.id===id);
    if(!c)return;
    if(!confirm('Excluir a conta "'+c.nome+'"?'))return;
    D.contasBanco=D.contasBanco.filter(x=>x.id!==id);
    auditar('EXCLUSAO','financeiro','Conta bancária excluída: '+c.nome);
    sv();rdContasBanco();
    toast('Conta excluída','ok');
  });
}
function tipoContaLabel(t){return t==='poupanca'?'Poupança':t==='aplicacao'?'Aplicação':'Corrente';}
function rdContasBanco(){
  const el=document.getElementById('contas-banco-lista');
  if(!el)return;
  const contas=D.contasBanco||[];
  if(!contas.length){el.innerHTML='<p class="empty" style="padding:10px">Nenhuma conta cadastrada. Clique em + Conta.</p>';
    const st=document.getElementById('saldo-total-banco');if(st)st.textContent=fmt(0);return;}
  el.innerHTML='<div class="tw"><table><thead><tr><th>Conta</th><th>Banco</th><th>Ag/Conta</th><th>Tipo</th><th>Saldo</th><th>Poup./Aplic.</th><th>Fluxo</th><th></th></tr></thead><tbody>'+
    contas.map(c=>`<tr>
      <td><b>${c.nome}</b></td>
      <td style="font-size:11px">${c.banco||'-'}</td>
      <td style="font-size:11px">${c.ag||'-'} / ${c.conta||'-'}</td>
      <td><span class="badge ${c.tipo==='aplicacao'?'b-pu':c.tipo==='poupanca'?'b-cy':'b-bl'}">${tipoContaLabel(c.tipo)}</span></td>
      <td style="color:var(--gn);font-weight:600">${fmt(c.saldo)}</td>
      <td style="color:var(--bl)">${fmt(c.saldoPA)}</td>
      <td>${c.noFluxo!==false?'<span class="badge b-gn">Sim</span>':'<span class="badge b-gr">Não</span>'}</td>
      <td style="display:flex;gap:4px"><button class="btn bw btn-xs" onclick="ajustarSaldoBanco('${c.id}')" title="Acerto de saldo (motivo + senha do solicitante)">⚖️ Acerto</button><button class="btn bw btn-xs" onclick="editContaBanco('${c.id}')" title="Editar">✏️</button><button class="btn bd btn-xs" onclick="delContaBanco('${c.id}')" title="Excluir">×</button></td>
    </tr>`).join('')+'</tbody></table></div>';
  // Saldo total das contas que entram no fluxo
  const total=contas.filter(c=>c.noFluxo!==false).reduce((s,c)=>s+(c.saldo||0)+(c.saldoPA||0),0);
  const st=document.getElementById('saldo-total-banco');if(st)st.textContent=fmt(total);
}

// ---- FLUXO BANCÁRIO: pagar/receber selecionando conta e abatendo/somando saldo ----
let _opBanco=null;
function _parseValorBR(s){ if(s==null)return NaN; s=String(s).trim().replace(/\s/g,''); if(s.indexOf(',')>-1){s=s.replace(/\./g,'').replace(',','.');} return parseFloat(s); }
function abrirSelBanco(modo, id, tipo, valor, desc){
  const bancos=D.contasBanco||[];
  if(!bancos.length){ alert('Cadastre uma conta bancária primeiro (Financeiro → Fluxo de Caixa → + Conta).'); return false; }
  _opBanco={modo,id,tipo,valor,desc};
  const tit=document.getElementById('selbanco-titulo');
  const sub=document.getElementById('selbanco-sub');
  const cont=document.getElementById('selbanco-lista');
  if(tit)tit.textContent=(modo==='pagar'?'💸 Pagar ':'💰 Receber ')+fmt(valor);
  if(sub)sub.textContent=(desc||'')+' — selecione a conta bancária:';
  if(cont)cont.innerHTML=bancos.map(c=>`<button class="btn bp" style="width:100%;margin-bottom:7px;text-align:left;padding:11px 13px" onclick="confirmarOpBanco('${c.id}')">🏦 <b>${c.nome}</b>${c.banco?' ('+c.banco+')':''}<span style="float:right;color:var(--gn)">${fmt((c.saldo||0)+(c.saldoPA||0))}</span></button>`).join('');
  openM('m-sel-banco');
  return true;
}
function confirmarOpBanco(contaId){
  if(!_opBanco)return;
  const c=(D.contasBanco||[]).find(x=>x.id===contaId);
  if(!c){toast('Conta não encontrada','er');return;}
  const op=_opBanco; _opBanco=null;
  if(op.modo==='pagar'){
    c.saldo=(c.saldo||0)-op.valor;
    const item = op.tipo==='NF'? (D.nfs||[]).find(n=>n.id===op.id) : (D.despesas||[]).find(d=>d.id===op.id);
    if(item){ item.st='pago'; item.dtPag=new Date().toISOString().substring(0,10); item.contaBanco=c.nome; item.contaBancoId=c.id; }
    if(typeof auditarExclusao==='function')auditarExclusao('contasBanco','PAGAMENTO '+fmt(op.valor)+' de '+c.nome+' ('+(op.desc||'')+')');
    toast('✅ Pago e abatido de '+c.nome,'ok');
  } else {
    c.saldo=(c.saldo||0)+op.valor;
    const lista=op.tipo==='med'?D.medicoes:D.vendas;
    const x=(lista||[]).find(i=>i.id===op.id);
    if(x){ x.st=op.tipo==='med'?'paga':'pago'; x.prejuizo=false; x.fluxo='sim'; x.dtPag=new Date().toISOString().substring(0,10); x.contaBanco=c.nome; x.contaBancoId=c.id; }
    if(typeof auditarExclusao==='function')auditarExclusao('contasBanco','RECEBIMENTO '+fmt(op.valor)+' em '+c.nome+' ('+(op.desc||'')+')');
    toast('✅ Recebido e somado em '+c.nome,'ok');
  }
  closeM('m-sel-banco');
  sv();
  if(typeof rdFin==='function')rdFin();
  if(typeof rdContasReceber==='function')rdContasReceber();
  if(typeof rdFluxo==='function')rdFluxo();
  if(typeof rdContasBanco==='function')rdContasBanco();
}
function ajustarSaldoBanco(id){
  const c=(D.contasBanco||[]).find(x=>x.id===id);
  if(!c)return;
  document.getElementById('as-id').value=id;
  document.getElementById('as-conta').value=c.nome+(c.banco?' ('+c.banco+')':'');
  var _q=document.getElementById('as-qual'); if(_q)_q.value='saldo';
  document.getElementById('as-atual').value=fmt(c.saldo||0);
  document.getElementById('as-novo').value=String((c.saldo||0)).replace('.',',');
  document.getElementById('as-motivo').value='';
  document.getElementById('as-senha').value='';
  var lbl=document.getElementById('as-senha-lbl'); if(lbl)lbl.textContent='Senha de '+((authUser&&authUser.nome)||'usuário logado')+' *';
  var st=document.getElementById('as-status'); if(st)st.textContent='';
  openM('m-acerto-saldo');
}
function _acertoTrocaQual(){
  var id=document.getElementById('as-id').value;
  var c=(D.contasBanco||[]).find(function(x){return x.id===id;}); if(!c)return;
  var qual=(document.getElementById('as-qual')||{}).value||'saldo';
  var atual=(qual==='saldoPA'?(c.saldoPA||0):(c.saldo||0));
  document.getElementById('as-atual').value=fmt(atual);
  document.getElementById('as-novo').value=String(atual).replace('.',',');
}
async function _validarSenhaSolicitante(senha){
  if(!senha) return false;
  var login=(authUser&&authUser.login)||'';
  if(!login){var _lu=(D.usuarios||[]).find(function(x){return (x.nm||x.nome||'')===((authUser&&authUser.nome)||'');});if(_lu)login=(_lu.lg||_lu.login||'');}
  try{
    if(typeof syncAtivo!=='undefined' && syncAtivo && typeof authToken!=='undefined' && authToken && !String(authToken).startsWith('local_') && login){
      var r=await fetch('api.php?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({login:login,senha:senha})});
      var j=await r.json();
      if(j&&j.ok) return true; // servidor confirmou
      // se o servidor recusou, ainda tenta a checagem local (senha do usuário OU senha de administrador)
    }
  }catch(e){}
  var nome=(authUser&&authUser.nome)||'';
  var u=(D.usuarios||[]).find(function(x){var xl=(x.lg||x.login||'').toLowerCase(),xn=(x.nm||x.nome||'');return (login&&xl===login.toLowerCase())||(nome&&xn===nome);});
  var upw=u&&(u.pw||u.senha);
  if(upw!=null&&upw!=='' && String(upw)===String(senha)) return true;
  if(D.config&&D.config.admPw && String(D.config.admPw)===String(senha)) return true;
  return false;
}
async function confirmarAcertoSaldo(){
  var id=document.getElementById('as-id').value;
  var c=(D.contasBanco||[]).find(x=>x.id===id);
  var st=document.getElementById('as-status'); var setSt=function(m){if(st){st.style.color='var(--rd)';st.textContent=m;}};
  if(!c){setSt('Conta não encontrada.');return;}
  var qual=(document.getElementById('as-qual')||{}).value||'saldo';
  var qualLbl=(qual==='saldoPA')?'Saldo poupança/aplicação':'Saldo corrente';
  var v=_parseValorBR(document.getElementById('as-novo').value);
  if(isNaN(v)){setSt('Informe um novo saldo válido.');return;}
  var motivo=(document.getElementById('as-motivo').value||'').trim();
  if(!motivo){setSt('O motivo é obrigatório.');return;}
  var senha=document.getElementById('as-senha').value;
  if(!senha){setSt('Digite sua senha.');return;}
  if(st){st.style.color='var(--mt)';st.textContent='Validando senha...';}
  var ok=await _validarSenhaSolicitante(senha);
  if(!ok){setSt('❌ Senha incorreta. Acerto cancelado.');return;}
  var antigo=(qual==='saldoPA'?(c.saldoPA||0):(c.saldo||0));
  if(qual==='saldoPA') c.saldoPA=v; else c.saldo=v;
  var quem=(authUser&&authUser.nome)||'?'; var login=(authUser&&authUser.login)||'';
  c.ajustesSaldo=c.ajustesSaldo||[];
  c.ajustesSaldo.push({data:new Date().toISOString(), quem:quem, login:login, qual:qual, de:antigo, para:v, motivo:motivo});
  if(typeof auditarExclusao==='function')auditarExclusao('contasBanco','ACERTO DE SALDO ('+qualLbl+') — '+c.nome+': '+fmt(antigo)+' → '+fmt(v)+' | Solicitante: '+quem+(login?' ('+login+')':'')+' | Motivo: '+motivo);
  sv(); if(typeof rdContasBanco==='function')rdContasBanco(); if(typeof rdFluxo==='function')rdFluxo(); if(typeof carregarBancosCfg==='function')carregarBancosCfg();
  closeM('m-acerto-saldo');
  toast(qualLbl+' de '+c.nome+' ajustado para '+fmt(v),'ok');
}

function saldoBancarioFluxo(){
  return (D.contasBanco||[]).filter(c=>c.noFluxo!==false).reduce((s,c)=>s+(c.saldo||0)+(c.saldoPA||0),0);
}

