// ---- LEMBRETE DE ANIVERSÁRIO (item 5b) ----
function getAniversariantesAmanha(){
  const amanha=new Date();amanha.setDate(amanha.getDate()+1);
  const mm=String(amanha.getMonth()+1).padStart(2,'0');
  const dd=String(amanha.getDate()).padStart(2,'0');
  return (D.funcionarios||[]).filter(f=>{
    if(!f.nasc)return false;
    const m=f.nasc.match(/^(\d{4})-(\d{2})-(\d{2})/);
    return m && m[2]===mm && m[3]===dd;
  });
}
function rdAniversarios(){
  const el=document.getElementById('d-aniversarios');
  if(!el)return;
  // Só usuários autorizados (lista em D.config.aniversarioUsers; admin sempre vê)
  if(!temAcesso('aniversarios')){el.innerHTML='';return;}
  const aniv=getAniversariantesAmanha();
  if(!aniv.length){el.innerHTML='';return;}
  el.innerHTML=`<div class="panel" style="border:2px solid var(--pu)">
    <div class="ph"><div class="pt">🎂 Aniversário Amanhã!</div></div>
    <div class="pb">${aniv.map(f=>`<div style="padding:6px 0;font-size:13px">🎉 <b>${f.nome}</b>${f.cargo?' — '+f.cargo:''} faz aniversário amanhã!</div>`).join('')}</div>
  </div>`;
}

// ---- AJUDAS RECORRENTES (confirmação mensal) ----
function ajudasAConfirmar(){
  const mes=new Date().toISOString().substring(0,7);
  const user=(authUser&&authUser.nome)||'';
  if(!temAcesso('confirma-ajuda') && !((D.usuarios||[]).find(x=>x.nome===user))) return [];
  return (D.ajudasMotorista||[]).filter(a=>
    a.recorrente && a.confirmaUser===user && !(a.mesesTratados||[]).includes(mes)
  );
}
function rdAjudasRecorrentes(){
  const el=document.getElementById('d-ajudas-recorrentes');
  if(!el)return;
  const pend=ajudasAConfirmar();
  if(!pend.length){el.innerHTML='';return;}
  const mes=new Date().toISOString().substring(0,7);
  el.innerHTML=`<div class="panel" style="border:2px solid var(--or)">
    <div class="ph"><div class="pt">🔁 Ajudas de Custo a Confirmar (${mes})</div><span class="badge b-or">${pend.length}</span></div>
    <div class="pb">
      <p style="font-size:11px;color:var(--mt)">Confirme se cada ajuda recorrente entra no Contas a Pagar este mês:</p>
      ${pend.map(a=>`<div style="display:flex;justify-content:space-between;align-items:center;padding:8px;border-bottom:1px solid var(--br)">
        <div><b>${a.motorista}</b> — ${a.empresa} <span class="badge b-bl" style="font-size:9px">${a.placa||''}</span><br>
        <span style="font-size:11px;color:var(--red)">${fmt(a.valor)}</span></div>
        <div style="display:flex;gap:6px">
          <button class="btn bp btn-sm" onclick="confirmarAjudaRecorrente('${a.id}')" title="Lançar no Contas a Pagar">✅ Confirmar</button>
          <button class="btn bg btn-sm" onclick="pularAjudaRecorrente('${a.id}')" title="Não lançar este mês">⏭ Pular</button>
        </div>
      </div>`).join('')}
    </div>
  </div>`;
}
function confirmarAjudaRecorrente(id){
  const a=(D.ajudasMotorista||[]).find(x=>x.id===id);
  if(!a)return;
  const mes=new Date().toISOString().substring(0,7);
  const hoje=new Date().toISOString().substring(0,10);
  const bancario=dadosBancariosTexto(a);
  D.despesas.push({
    id:uid(),desc:'AJUDA DE CUSTO — '+a.empresa+' — '+a.motorista+' (recorrente '+mes+')',
    cat:'Ajuda de Custo',vl:a.valor,dt:hoje,vc:hoje,st:'pendente',fluxo:'sim',cp:'sim',
    forn:a.empresa,placa:a.placa||'',
    ob:bancario+(a.obs?' | Obs: '+a.obs:'')+(a.telefone?' | Tel: '+a.telefone:''),origemAjuda:id
  });
  a.mesesTratados=a.mesesTratados||[];a.mesesTratados.push(mes);
  auditar('CRIACAO','ajuda_motorista','Ajuda recorrente CONFIRMADA: '+a.motorista+' '+mes+' → Contas a Pagar');
  sv();rdAjudasRecorrentes();if(typeof rdDash==='function')rdDash();
  toast('Ajuda confirmada e lançada em Contas a Pagar!','ok');
}
function pularAjudaRecorrente(id){
  const a=(D.ajudasMotorista||[]).find(x=>x.id===id);
  if(!a)return;
  const mes=new Date().toISOString().substring(0,7);
  a.mesesTratados=a.mesesTratados||[];a.mesesTratados.push(mes);
  auditar('ALTERACAO','ajuda_motorista','Ajuda recorrente PULADA: '+a.motorista+' '+mes);
  sv();rdAjudasRecorrentes();
  toast('Ajuda pulada este mês (não lançada).','ok');
}

// ---- SAÍDA DE MATERIAL (Almoxarifado, nota mensal) ----
function mesAtualSM(){
  const el=document.getElementById('sm-mes');
  return (el&&el.value)?el.value:new Date().toISOString().substring(0,7);
}
function rdSaidaMaterial(){
  // Popula produtos da categoria Almoxarifado
  const sel=document.getElementById('sm-prod');
  if(sel){
    const atual=sel.value;
    sel.innerHTML='<option value="">Selecionar produto...</option>';
    D.estoque.filter(e=>(e.cat||'').toLowerCase().includes('almoxarifado')).forEach(e=>{
      sel.innerHTML+=`<option value="${e.id}">${e.cd?e.cd+' — ':''}${e.ds} (estoque: ${e.qt||0})</option>`;
    });
    if(atual)sel.value=atual;
  }
  const dtEl=document.getElementById('sm-dt');
  if(dtEl&&!dtEl.value)dtEl.value=new Date().toISOString().substring(0,10);
  const mesEl=document.getElementById('sm-mes');
  if(mesEl&&!mesEl.value)mesEl.value=new Date().toISOString().substring(0,7);
  // Render nota do mês
  const mes=mesAtualSM();
  const tb=document.getElementById('sm-tb');
  if(!tb)return;
  const itens=(D.saidasMaterial||[]).filter(s=>s.dt&&s.dt.startsWith(mes));
  const fechada=(D.saidasMaterial||[]).some(s=>s.dt&&s.dt.startsWith(mes)&&s.fechada);
  const total=itens.reduce((s,i)=>s+(i.qtd*i.vlUnit),0);
  tb.innerHTML=itens.length?itens.map(s=>`<tr>
    <td style="font-size:11px">${fmtData(s.dt)}</td>
    <td><b>${s.prodNome}</b></td>
    <td>${s.qtd}</td>
    <td>${fmt(s.vlUnit)}</td>
    <td style="color:var(--or);font-weight:600">${fmt(s.qtd*s.vlUnit)}</td>
    <td>${s.fechada?'🔒':`<button class="btn bd btn-xs" onclick="delSaidaMaterial('${s.id}')" title="Excluir lançamento">×</button>`}</td>
  </tr>`).join(''):'<tr><td colspan="6" class="empty">Nenhuma saída lançada neste mês</td></tr>';
  const tEl=document.getElementById('sm-total');if(tEl)tEl.textContent=fmt(total);
  const stEl=document.getElementById('sm-status');
  if(stEl)stEl.textContent=fechada?'🔒 NOTA FECHADA — já lançada como despesa':'📂 Nota ABERTA (fecha no último dia do mês ou pelo botão Fechar Mês)';
}
function addSaidaMaterial(){
  const prodId=document.getElementById('sm-prod').value;
  const qtd=parseFloat(document.getElementById('sm-qtd').value)||0;
  const dt=document.getElementById('sm-dt').value;
  if(!prodId){toast('Selecione o produto (categoria Almoxarifado)','er');return;}
  if(!qtd||qtd<=0){toast('Informe a quantidade','er');return;}
  if(!dt){toast('Informe a data','er');return;}
  const prod=D.estoque.find(e=>e.id===prodId);
  if(!prod){toast('Produto não encontrado','er');return;}
  if((prod.qt||0)<qtd){toast('Estoque insuficiente! Disponível: '+(prod.qt||0),'er');return;}
  const mes=dt.substring(0,7);
  if((D.saidasMaterial||[]).some(s=>s.dt&&s.dt.startsWith(mes)&&s.fechada)){
    toast('🔒 A nota deste mês já foi FECHADA. Não é possível lançar.','er');return;
  }
  // Baixa do estoque + lançamento na nota
  prod.qt=(prod.qt||0)-qtd;
  D.saidasMaterial.push({
    id:uid(),dt,prodId,prodNome:prod.ds,cod:prod.cd||'',
    qtd,vlUnit:parseFloat(prod.cv)||0,fechada:false
  });
  auditar('CRIACAO','saida_material','Saída: '+qtd+'x '+prod.ds+' ('+fmtData(dt)+')');
  document.getElementById('sm-qtd').value='';
  sv();rdSaidaMaterial();rdEstq&&rdEstq();
  toast('Saída lançada! Estoque baixado.','ok');
}
function delSaidaMaterial(id){
  reqSenha(()=>{
    const s=(D.saidasMaterial||[]).find(x=>x.id===id);
    if(!s)return;
    if(s.fechada){toast('Nota fechada não pode ser alterada','er');return;}
    if(!confirm('Excluir este lançamento? A quantidade volta ao estoque.'))return;
    const prod=D.estoque.find(e=>e.id===s.prodId);
    if(prod)prod.qt=(prod.qt||0)+s.qtd;
    D.saidasMaterial=D.saidasMaterial.filter(x=>x.id!==id);
    auditar('EXCLUSAO','saida_material','Saída excluída: '+s.qtd+'x '+s.prodNome);
    sv();rdSaidaMaterial();
    toast('Lançamento excluído, estoque devolvido','ok');
  });
}
function fecharNotaMes(){
  const mes=mesAtualSM();
  const itens=(D.saidasMaterial||[]).filter(s=>s.dt&&s.dt.startsWith(mes)&&!s.fechada);
  if(!itens.length){toast('Nenhum lançamento aberto neste mês','er');return;}
  const total=itens.reduce((s,i)=>s+(i.qtd*i.vlUnit),0);
  reqSenha(()=>{
    if(!confirm('FECHAR a nota de '+mes+'?\n\nTotal: '+fmt(total)+'\nSerá lançado como DESPESA (−) nos resultados da empresa.\nApós o fechamento não pode mais lançar neste mês.'))return;
    itens.forEach(s=>s.fechada=true);
    // Lança como despesa nos resultados
    const ultimoDia=new Date(parseInt(mes.substring(0,4)),parseInt(mes.substring(5,7)),0).getDate();
    D.despesas.push({
      id:uid(),desc:'CONSUMO ALMOXARIFADO — '+mes,cat:'Almoxarifado',
      vl:total,dt:mes+'-'+String(ultimoDia).padStart(2,'0'),vc:mes+'-'+String(ultimoDia).padStart(2,'0'),
      st:'pendente',fluxo:'sim',cp:'sim',forn:'Almoxarifado MH3',origemSM:mes
    });
    auditar('FECHAMENTO','saida_material','Nota '+mes+' FECHADA: '+fmt(total)+' lançado como despesa');
    sv();rdSaidaMaterial();
    toast('🔒 Nota fechada! '+fmt(total)+' lançado como despesa nos resultados.','ok');
  });
}
function verNotaMes(){
  const mes=mesAtualSM();
  const itens=(D.saidasMaterial||[]).filter(s=>s.dt&&s.dt.startsWith(mes));
  if(!itens.length){toast('Nenhum lançamento neste mês','er');return;}
  rdSaidaMaterial();
  toast('🔍 Nota de '+mes+' exibida na tabela ('+itens.length+' lançamentos)','ok');
}
function imprimirNotaMes(){
  const mes=mesAtualSM();
  const itens=(D.saidasMaterial||[]).filter(s=>s.dt&&s.dt.startsWith(mes));
  if(!itens.length){toast('Nenhum lançamento neste mês para imprimir','er');return;}
  const total=itens.reduce((s,i)=>s+(i.qtd*i.vlUnit),0);
  const fechada=itens.some(s=>s.fechada);
  // Agrupa por produto (somatório)
  const porProd={};
  itens.forEach(s=>{
    if(!porProd[s.prodNome])porProd[s.prodNome]={qtd:0,vlUnit:s.vlUnit,cod:s.cod};
    porProd[s.prodNome].qtd+=s.qtd;
  });
  let h=`<html><head><title>Nota Almoxarifado ${mes}</title>
  <style>@page{margin:15mm}@media print{body{padding:0!important}}body{font-family:Arial;padding:20px}h1{font-size:18px}table{width:100%;border-collapse:collapse;margin:10px 0}td,th{border:1px solid #ccc;padding:6px;font-size:12px;text-align:left}</style>
  </head><body>
  <h1>MH3 RENTAL — NOTA DE SAÍDA DE MATERIAL (ALMOXARIFADO)</h1>
  <p><b>Mês:</b> ${mes} | <b>Status:</b> ${fechada?'🔒 FECHADA':'📂 ABERTA'}</p>
  <h3>Resumo por Produto</h3>
  <table><tr><th>Código</th><th>Produto</th><th>Qtd Total</th><th>Valor Unit.</th><th>Total</th></tr>`;
  Object.keys(porProd).forEach(p=>{
    const d=porProd[p];
    h+=`<tr><td>${d.cod||'-'}</td><td>${p}</td><td>${d.qtd}</td><td>${fmt(d.vlUnit)}</td><td>${fmt(d.qtd*d.vlUnit)}</td></tr>`;
  });
  h+=`</table>
  <h3>Lançamentos Detalhados</h3>
  <table><tr><th>Data</th><th>Produto</th><th>Qtd</th><th>Total</th></tr>`;
  itens.forEach(s=>{h+=`<tr><td>${fmtData(s.dt)}</td><td>${s.prodNome}</td><td>${s.qtd}</td><td>${fmt(s.qtd*s.vlUnit)}</td></tr>`;});
  h+=`</table>
  <p style="font-size:16px"><b>TOTAL DO MÊS: ${fmt(total)}</b></p>
  <p style="font-size:10px;color:#666">Impresso em ${new Date().toLocaleDateString('pt-BR')} ${new Date().toLocaleTimeString('pt-BR')}</p>
  </body></html>`;
  const w=window.open('','_blank');
  w.document.write(h);w.document.close();
  setTimeout(()=>w.print(),500);
  auditar('IMPRESSAO','saida_material','Nota '+mes+' impressa');
}

// ---- CLIENTES ----
function rdRelCli(){
  const{meds,vends,desps}=getRelData();
  const busca=(document.getElementById('rel-busca').value||'').toLowerCase();
  const todos=[...new Set([...meds.map(m=>m.cl),...vends.map(v=>v.cli),...D.contratos.map(c=>c.cl)])].filter(Boolean).filter(c=>!busca||c.toLowerCase().includes(busca));

  const tabRes=`<div class="panel"><div class="ph"><div class="pt">Clientes — Resumo</div><span style="font-size:9px;color:var(--mt)">${todos.length} clientes</span></div><div class="tw"><table><thead><tr><th>#</th><th>Cliente</th><th>Contratos</th><th>Rec. Medições</th><th>Rec. Vendas</th><th>Total Geral</th></tr></thead><tbody>
  ${todos.map((cl,i)=>{const nct=D.contratos.filter(c=>c.cl===cl).length;const rm=meds.filter(m=>m.cl===cl).reduce((s,m)=>s+(m.total||0),0);const rv=vends.filter(v=>v.cli===cl).reduce((s,v)=>s+(v.total||0),0);return`<tr><td style="font-size:9px;color:var(--mt)">${i+1}</td><td><b>${cl}</b></td><td>${nct}</td><td style="color:var(--gn)">${rm?fmt(rm):'-'}</td><td style="color:var(--pu)">${rv?fmt(rv):'-'}</td><td style="color:var(--gn);font-weight:600">${fmt(rm+rv)}</td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">Sem dados</td></tr>'}</tbody></table></div></div>`;

  const tabDet=todos.map(cl=>{
    const cts=D.contratos.filter(c=>c.cl===cl);const mCl=meds.filter(m=>m.cl===cl);const vCl=vends.filter(v=>v.cli===cl);const rm=mCl.reduce((s,m)=>s+(m.total||0),0);const rv=vCl.reduce((s,v)=>s+(v.total||0),0);
    return`<div class="panel" style="margin-bottom:10px"><div class="ph"><div class="pt">👤 ${cl}</div><div style="font-family:'Bebas Neue';font-size:18px;color:var(--gn)">${fmt(rm+rv)}</div></div><div class="pb">
    <div class="g2" style="margin-bottom:10px">
      <div><div style="font-size:9px;color:var(--mt);margin-bottom:5px">CONTRATOS (${cts.length})</div>${cts.map(c=>`<div class="stat-row"><div class="stat-label"><span class="tag-p">${c.placa||'-'}</span> ${c.ob||''}</div><div class="stat-value">${fmt(c.vl)}/mês · ${bdg(c.status)}</div></div>`).join('')||'-'}</div>
      <div><div style="font-size:9px;color:var(--mt);margin-bottom:5px">MEDIÇÕES (${mCl.length})</div>${mCl.map(m=>`<div class="stat-row"><div class="stat-label">${m.ms||''}</div><div style="display:flex;align-items:center;gap:6px;font-size:11px">${fmt(m.total)} ${bdg(m.st)}</div></div>`).join('')||'-'}</div>
    </div>
    ${vCl.length?`<div style="font-size:9px;color:var(--mt);margin-bottom:5px">VENDAS (${vCl.length})</div>${vCl.map(v=>`<div class="stat-row"><div class="stat-label">${v.num} · ${v.dt||''}</div><div style="display:flex;align-items:center;gap:6px;font-size:11px">${fmt(v.total)} ${bdg(v.st)}</div></div>`).join('')}`:''}
    </div></div>`;}).join('');

  document.getElementById('rel-cli').innerHTML=granBlock('',tabRes,tabRes+tabDet,tabRes+tabDet);}

// ---- ESTOQUE ----
function rdRelEstq(){
  const{mns,vends}=getRelData();
  const busca=(document.getElementById('rel-busca').value||'').toLowerCase();
  let items=D.estoque;if(busca)items=items.filter(e=>`${e.ds} ${e.cat} ${e.cd||''}`.toLowerCase().includes(busca));
  const vl=items.reduce((s,e)=>s+((Number(e.qt)||0)*(Number(e.cv)||0)),0);const bx=items.filter(e=>e.qt<=e.mn).length;
  const cats=[...new Set(items.map(e=>e.cat))];

  const kpis=`<div class="krow c3" style="margin-bottom:12px">
    <div class="kpi bl"><div class="klbl">Itens Cadastrados</div><div class="kval">${items.length}</div></div>
    <div class="kpi yw"><div class="klbl">Estoque Baixo</div><div class="kval">${bx}</div><div class="ksub">abaixo do mínimo</div></div>
    <div class="kpi gn"><div class="klbl">Valor em Estoque</div><div class="kval">${fmtk(vl)}</div></div>
  </div>`;

  const tabRes=`<div class="panel"><div class="ph"><div class="pt">Produtos — Resumo por Categoria</div></div><div class="tw"><table><thead><tr><th>Categoria</th><th>Itens</th><th>Qtd Total</th><th>Valor Estoque</th><th>Baixo Estoque</th></tr></thead><tbody>
  ${cats.map(cat=>{const its=items.filter(e=>e.cat===cat);const v=its.reduce((s,e)=>s+((Number(e.qt)||0)*(Number(e.cv)||0)),0);const bxc=its.filter(e=>e.qt<=e.mn).length;return`<tr><td><b>${cat}</b></td><td>${its.length}</td><td>${its.reduce((s,e)=>s+e.qt,0)}</td><td style="color:var(--gn)">${fmt(v)}</td><td>${bxc?`<span class="badge b-yw">${bxc} baixo</span>`:'-'}</td></tr>`;}).join('')||'<tr><td colspan="5" class="empty">Sem dados</td></tr>'}</tbody></table></div></div>`;

  const tabDet=`<div class="panel"><div class="ph"><div class="pt">Todos os Itens — Detalhado</div><span style="font-size:9px;color:var(--mt)">${items.length} itens</span></div><div class="tw"><table><thead><tr><th>Cód.</th><th>Descrição</th><th>Cat.</th><th>Qtd</th><th>Mín</th><th>Un</th><th>Custo</th><th>Venda</th><th>Margem</th><th>Total</th><th>Situação</th></tr></thead><tbody>
  ${items.map(e=>{const mg=e.pv&&e.cv?Math.round((e.pv-e.cv)/e.cv*100):0;return`<tr><td style="font-size:9px;color:var(--mt)">${e.cd||'-'}</td><td><b>${e.ds}</b></td><td style="font-size:9px">${e.cat}</td><td style="font-weight:700;${e.qt<=e.mn?'color:var(--yw)':''}">${e.qt}</td><td style="font-size:9px">${e.mn}</td><td style="font-size:9px">${e.un}</td><td>${fmt(e.cv)}</td><td style="color:var(--pu)">${fmt(e.pv||0)}</td><td style="color:${mg>0?'var(--gn)':'var(--mt)'};">${e.pv&&e.cv?mg+'%':'-'}</td><td style="color:var(--gn)">${fmt((Number(e.qt)||0)*(Number(e.cv)||0))}</td><td>${e.qt<=0?'<span class="badge b-rd">Zerado</span>':e.qt<=e.mn?'<span class="badge b-yw">Baixo</span>':'<span class="badge b-gn">OK</span>'}</td></tr>`;}).join('')||'<tr><td colspan="11" class="empty">Sem dados</td></tr>'}</tbody></table></div></div>`;

  const tabGiro=`<div class="panel"><div class="ph"><div class="pt">Giro de Estoque — Analítico</div></div><div class="tw"><table><thead><tr><th>Cód.</th><th>Descrição</th><th>Estoque Atual</th><th>Usado em OS</th><th>Usado em Vendas</th><th>Total Saídas</th><th>Custo Saídas</th></tr></thead><tbody>
  ${items.map(e=>{const usOS=mns.reduce((s,m)=>{const l=(m.lancs||[]).filter(l=>l.estqId===e.id);return s+l.reduce((ss,l)=>ss+l.qtd,0);},0);const usV=vends.reduce((s,v)=>{const i=(v.items||[]).filter(i=>i.estqId===e.id);return s+i.reduce((ss,i)=>ss+i.qtd,0);},0);if(!usOS&&!usV)return'';return`<tr><td style="font-size:9px">${e.cd||'-'}</td><td><b>${e.ds}</b></td><td>${e.qt} ${e.un}</td><td style="color:var(--yw)">${usOS?usOS+' '+e.un:'-'}</td><td style="color:var(--pu)">${usV?usV+' '+e.un:'-'}</td><td style="font-weight:600">${(usOS+usV)} ${e.un}</td><td style="color:var(--red)">${fmt((usOS+usV)*e.cv)}</td></tr>`;}).filter(Boolean).join('')||'<tr><td colspan="7" class="empty">Sem movimentações no período</td></tr>'}</tbody></table></div></div>`;

  document.getElementById('rel-estq-c').innerHTML=granBlock('',kpis+tabRes,kpis+tabDet,kpis+tabDet+tabGiro);}

