function relFrotaVencimentos(){
  var eqs=D.equips||[];
  if(!eqs.length){toast('Nenhum veículo/equipamento','er');return;}
  var hoje=new Date();hoje.setHours(0,0,0,0);
  var docs=[{k:'crlv',l:'CRLV'},{k:'antt',l:'Licença/ANTT'},{k:'crono',l:'Cronotacógrafo'},{k:'vseg',l:'Seguro'}];
  var linhas=[];
  eqs.forEach(function(e){
    docs.forEach(function(d){
      var v=e[d.k];
      if(v){var dt=new Date(v);var dias=Math.round((dt-hoje)/86400000);linhas.push({placa:e.placa,mkmo:(e.mk||'')+' '+(e.mo||''),doc:d.l,venc:v,dias:dias});}
    });
  });
  linhas.sort(function(a,b){return a.dias-b.dias;});
  var h='<html><head><title>Vencimentos de Documentos — Frota</title><style>@page{margin:14mm}body{font-family:Arial;padding:18px}h1{font-size:16px}p{font-size:11px;color:#666}table{width:100%;border-collapse:collapse;margin-top:10px}td,th{border:1px solid #ccc;padding:6px;font-size:11px;text-align:left}th{background:#1E5FAA;color:#fff}.venc{background:#ffd6d6;font-weight:700}.prox{background:#fff3cd}</style></head><body>';
  h+='<h1>MH3 RENTAL — VENCIMENTOS DE DOCUMENTOS</h1><p>Gerado em '+new Date().toLocaleDateString('pt-BR')+' — '+linhas.length+' documento(s). Vermelho = vencido; amarelo = vence em até 30 dias.</p>';
  if(!linhas.length){h+='<p>Nenhum documento com data de vencimento cadastrada.</p>';}
  else{
    h+='<table><thead><tr><th>Placa</th><th>Veículo</th><th>Documento</th><th>Vencimento</th><th>Situação</th></tr></thead><tbody>';
    linhas.forEach(function(l){
      var cls=l.dias<0?'venc':(l.dias<=30?'prox':'');
      var sit=l.dias<0?('Vencido há '+Math.abs(l.dias)+' dia(s)'):(l.dias===0?'Vence hoje':('Faltam '+l.dias+' dia(s)'));
      h+='<tr class="'+cls+'"><td>'+escH(l.placa)+'</td><td>'+escH(l.mkmo)+'</td><td>'+escH(l.doc)+'</td><td>'+fmtData(l.venc)+'</td><td>'+sit+'</td></tr>';
    });
    h+='</tbody></table>';
  }
  h+='</body></html>';
  var w=window.open('','_blank');w.document.write(h);w.document.close();setTimeout(function(){w.print();},500);
  if(typeof auditar==='function')auditar('IMPRESSAO','frota','Relatório de vencimentos impresso');
}

function relFrotaPorTipo(tipo){
  var eqs=(D.equips||[]).filter(function(e){return e.st!=='vendido';});
  if(!eqs.length){ if(typeof toast==='function')toast('Nenhum veículo/equipamento','er'); return; }
  var nomes={crlv:'CRLV',antt:'Licença / ANTT',crono:'Cronotacógrafo',docManVc:'Doc. Manual',seguro:'Seguro'};
  var nome=nomes[tipo]||tipo;
  var hoje=new Date();hoje.setHours(0,0,0,0);
  var getVal=function(e){
    if(tipo==='seguro'){var s=(typeof _segAtivoVeic==='function')?_segAtivoVeic(e.placa):null;return s?(s.venc||''):'';}
    return e[tipo]||'';
  };
  var linhas=eqs.map(function(e){
    var v=getVal(e); var dias=null, sit='', cls='';
    if(v){ var dt=new Date(String(v).length===10?(v+'T00:00:00'):v); dias=Math.round((dt-hoje)/86400000);
      if(dias<0){sit='Vencido há '+Math.abs(dias)+'d';cls='venc';}
      else if(dias<=30){sit='Vence em '+dias+'d';cls='prox';}
      else {sit='Em dia';cls='';}
    } else { sit='— EM BRANCO —'; cls='branco'; }
    return {placa:e.placa||'?', mkmo:((e.mk||'')+' '+(e.mo||'')).trim(), venc:v, sit:sit, cls:cls, temData:!!v};
  });
  linhas.sort(function(a,b){ if(a.temData!==b.temData) return a.temData?1:-1; return (a.venc||'').localeCompare(b.venc||''); });
  var emBranco=linhas.filter(function(l){return !l.temData;}).length;
  var h='<html><head><title>Conferência — '+escH(nome)+'</title><style>@page{margin:14mm}body{font-family:Arial;padding:18px}h1{font-size:16px}p{font-size:11px;color:#666}table{width:100%;border-collapse:collapse;margin-top:10px}td,th{border:1px solid #ccc;padding:6px;font-size:11px;text-align:left}th{background:#1E5FAA;color:#fff}.venc{background:#ffd6d6;font-weight:700}.prox{background:#fff3cd}.branco{background:#e9ecef;color:#b91c1c;font-weight:700}</style></head><body>';
  h+='<h1>MH3 RENTAL — CONFERÊNCIA DE '+escH(String(nome).toUpperCase())+'</h1>';
  h+='<p>Gerado em '+new Date().toLocaleDateString('pt-BR')+' — '+linhas.length+' veículo(s) · <b>'+emBranco+' em branco</b> (cinza). Vermelho = vencido; amarelo = vence em até 30 dias.</p>';
  h+='<table><thead><tr><th>Placa</th><th>Veículo</th><th>'+escH(nome)+'</th><th>Situação</th></tr></thead><tbody>';
  linhas.forEach(function(l){
    h+='<tr class="'+l.cls+'"><td>'+escH(l.placa)+'</td><td>'+escH(l.mkmo)+'</td><td>'+(l.venc?fmtData(l.venc):'—')+'</td><td>'+escH(l.sit)+'</td></tr>';
  });
  h+='</tbody></table></body></html>';
  var w=window.open('','_blank');w.document.write(h);w.document.close();setTimeout(function(){w.print();},500);
  if(typeof auditar==='function')auditar('IMPRESSAO','frota','Conferência por tipo ('+nome+') — '+emBranco+' em branco');
}

function gerarParcelasFaltantes(){
  var base=(D.equips||[]).filter(function(e){return (e.situ==='financiado'||e.situ==='consorcio') && parseInt(e.nparc||0)>0;});
  if(!base.length){toast('Nenhum veículo financiado/consórcio com parcelas a gerar.','er');return;}
  var jaTem=function(eq){return (D.nfs||[]).some(function(n){return n.eqId===eq.id && n.travada && n.parcela;});};
  var faltantes=base.filter(function(e){return !jaTem(e);});
  var fixas=faltantes.filter(function(e){return (e.tparc||'fixa')!=='variavel';});
  var varsPend=faltantes.length-fixas.length;
  if(!faltantes.length){toast('Todos os veículos financiados/consórcio já têm parcelas no Contas a Pagar.','ok');return;}
  if(!fixas.length){toast(varsPend+' veículo(s) de parcela variável: lance abrindo o cadastro (Editar → Salvar).','er');return;}
  if(!confirm('Gerar parcelas no Contas a Pagar para '+fixas.length+' veículo(s) que ainda não têm?'+(varsPend?' ('+varsPend+' de parcela variável serão ignorados — faça pelo cadastro)':'')+'\nOs que já têm parcelas não serão alterados.'))return;
  var total=0;
  fixas.forEach(function(e){var n=parseInt(e.nparc||0)||0;if(n>0){lancarParcelasContaPagar(e,n,'fixa',e.vparc||0,e.d1parc||'',e.banco||'',e.situ);total+=n;}});
  sv();if(typeof rdFin==='function')rdFin();if(typeof rdFrota==='function')rdFrota();
  toast(fixas.length+' veículo(s) — '+total+' parcela(s) lançada(s) no Contas a Pagar!'+(varsPend?' ('+varsPend+' variável ignorado)':''),'ok');
  if(typeof auditar==='function')auditar('LANCAMENTO','contas_pagar',total+' parcelas geradas (faltantes)');
}


// ---- RELATÓRIO ANALÍTICO POR PERÍODO ----
function coletarRelPeriodo(){
  const de=document.getElementById('relp-de').value;
  const ate=document.getElementById('relp-ate').value;
  const tipo=document.getElementById('relp-tipo').value;
  if(!de||!ate){toast('Informe o período (De e Até)','er');return null;}
  const noPeriodo=(d)=>d&&d>=de&&d<=ate;
  let receber=[],pagar=[];
  if(tipo!=='pagar'){
    receber=[...D.medicoes.filter(m=>noPeriodo(m.vc||m.ms?(m.vc||m.ms+'-01'):'')).map(m=>({dt:m.vc||(m.ms+'-01'),cli:m.cl,desc:'Medição'+(m.numMed?' Nº'+String(m.numMed).padStart(3,'0'):''),placa:m.placa||'',vl:m.total||0,st:m.st})),
             ...D.vendas.filter(v=>noPeriodo(v.vc||v.dt)).map(v=>({dt:v.vc||v.dt,cli:v.cli,desc:'Venda '+(v.num?'VD-'+v.num:''),placa:'',vl:v.total||0,st:v.st}))];
  }
  if(tipo!=='receber'){
    pagar=[...D.despesas.filter(d=>noPeriodo(d.vc||d.dt)).map(d=>({dt:d.vc||d.dt,cli:d.forn||'',desc:d.desc,placa:d.placa||'',vl:parseFloat(d.vl)||0,st:d.st})),
           ...D.nfs.filter(n=>noPeriodo(n.vc||n.dt)).map(n=>({dt:n.vc||n.dt,cli:n.forn||'',desc:'NF '+(n.num||''),placa:'',vl:parseFloat(n.vl)||0,st:n.st||'pendente'}))];
  }
  receber.sort((a,b)=>(a.dt||'').localeCompare(b.dt||''));
  pagar.sort((a,b)=>(a.dt||'').localeCompare(b.dt||''));
  return {de,ate,tipo,receber,pagar};
}
function gerarRelPeriodo(){
  const r=coletarRelPeriodo();
  if(!r)return;
  const el=document.getElementById('relp-resultado');
  const totR=r.receber.reduce((s,x)=>s+x.vl,0);
  const totP=r.pagar.reduce((s,x)=>s+x.vl,0);
  let h='';
  const tabela=(itens,titulo,cor)=>{
    if(!itens.length)return '';
    let t=`<h4 style="margin:10px 0 6px;color:${cor}">${titulo} (${itens.length})</h4>
    <div class="tw"><table><thead><tr><th>Venc.</th><th>Cliente/Fornec.</th><th>Descrição</th><th>Placa</th><th>Valor</th><th>Status</th></tr></thead><tbody>`;
    itens.forEach(x=>{t+=`<tr><td style="font-size:11px">${fmtData(x.dt)}</td><td>${x.cli||'-'}</td><td style="font-size:11px">${x.desc||'-'}</td><td style="font-size:11px">${x.placa||'-'}</td><td style="color:${cor};font-weight:600">${fmt(x.vl)}</td><td style="font-size:10px">${x.st||'-'}</td></tr>`;});
    t+='</tbody></table></div>';
    return t;
  };
  if(r.tipo!=='pagar')h+=tabela(r.receber,'💰 A RECEBER — Total: '+fmt(totR),'var(--gn)');
  if(r.tipo!=='receber')h+=tabela(r.pagar,'💸 A PAGAR — Total: '+fmt(totP),'var(--red)');
  if(r.tipo==='tudo')h+=`<div style="margin-top:10px;padding:12px;background:var(--rg);border-radius:8px;text-align:right;font-size:15px"><b>SALDO DO PERÍODO: <span style="color:${totR-totP>=0?'var(--gn)':'var(--red)'}">${fmt(totR-totP)}</span></b></div>`;
  el.innerHTML=h||'<p class="empty">Nenhum lançamento no período</p>';
  auditar('RELATORIO','relatorios','Relatório período '+fmtData(r.de)+' a '+fmtData(r.ate)+' ('+r.tipo+')');
}
function imprimirRelPeriodo(){
  const r=coletarRelPeriodo();
  if(!r)return;
  gerarRelPeriodo();
  const conteudo=document.getElementById('relp-resultado').innerHTML;
  const w=window.open('','_blank');
  w.document.write(`<html><head><title>Relatório ${fmtData(r.de)} a ${fmtData(r.ate)}</title>
  <style>@page{margin:15mm}@media print{body{padding:0!important}}body{font-family:Arial;padding:20px}table{width:100%;border-collapse:collapse;margin:8px 0}td,th{border:1px solid #ccc;padding:5px;font-size:11px;text-align:left}h1{font-size:16px}h4{margin:12px 0 4px}</style></head><body>
  <h1>MH3 RENTAL — RELATÓRIO ANALÍTICO POR PERÍODO</h1>
  <p><b>Período:</b> ${fmtData(r.de)} a ${fmtData(r.ate)} | <b>Tipo:</b> ${r.tipo==='tudo'?'Receber + Pagar':r.tipo==='receber'?'Somente a Receber':'Somente a Pagar'}</p>
  ${conteudo}
  <p style="font-size:10px;color:#666;margin-top:16px">Impresso em ${new Date().toLocaleDateString('pt-BR')} ${new Date().toLocaleTimeString('pt-BR')}</p>
  </body></html>`);
  w.document.close();
  setTimeout(()=>w.print(),500);
  auditar('IMPRESSAO','relatorios','Relatório por período impresso');
}

function rdRelResGeral(){
  const el=document.getElementById('rel-resgeral-c');
  if(!el) return;
  const totRec=D.medicoes.filter(m=>m.st==='paga').reduce((s,m)=>s+(m.total||0),0)+D.vendas.filter(v=>v.st==='pago').reduce((s,v)=>s+(v.total||0),0);
  const totOS=D.manutencoes.filter(m=>!ehImpressao(m)).reduce((s,m)=>s+((m.lancs||[]).reduce((ss,l)=>ss+l.qtd*l.val,0)),0);
  const totDesp=D.despesas.reduce((s,d)=>s+(parseFloat(d.vl)||0),0);
  const totNf=D.nfs.filter(n=>n.cp==='sim').reduce((s,n)=>s+(parseFloat(n.vl)||0),0);
  // PREJUÍZOS (atrasados) entram como NEGATIVO no resultado geral
  const totPrej=(typeof totalPrejuizos==='function')?totalPrejuizos():0;
  const res=totRec-totOS-totDesp-totNf-totPrej;
  el.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px">
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">RECEITAS TOTAIS</div><div style="font-size:20px;font-weight:700;color:var(--gn)">${fmt(totRec)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">CUSTOS OS</div><div style="font-size:20px;font-weight:700;color:var(--red)">−${fmt(totOS)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">DESPESAS</div><div style="font-size:20px;font-weight:700;color:var(--red)">−${fmt(totDesp)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">NF/COMPRAS</div><div style="font-size:20px;font-weight:700;color:var(--red)">−${fmt(totNf)}</div></div>
    <div class="kpi" style="border-color:var(--red)"><div style="font-size:10px;color:var(--mt)">⚠️ PREJUÍZOS (atrasados)</div><div style="font-size:20px;font-weight:700;color:var(--red)">−${fmt(totPrej)}</div></div>
    <div class="kpi" style="border-color:${res>=0?'var(--gn)':'var(--red)'}"><div style="font-size:10px;color:var(--mt)">RESULTADO GERAL</div><div style="font-size:20px;font-weight:700;color:${res>=0?'var(--gn)':'var(--red)'}">${fmt(res)}</div></div>
  </div>
  <p style="font-size:11px;color:var(--mt);margin-top:10px">Fórmula: Receitas − Custos OS − Despesas − NF/Compras − Prejuízos = Resultado Geral</p>`;
}

// ---- RESULTADO POR PLACA ----
function goResultado(){
  // Populate plate selector
  const sel=document.getElementById('res-placa');
  if(sel){
    sel.innerHTML='<option value="">Todas as placas</option>';
    D.equips.forEach(e=>{sel.innerHTML+=`<option value="${e.id}">${e.placa} — ${e.mk} ${e.mo}</option>`;});
  }
  rdResultado();
}

function toggleResPeriodo(){
  const p=document.getElementById('res-periodo').value;
  const box=document.getElementById('res-custom-box');
  if(box) box.style.display=p==='custom'?'flex':'none';
  rdResultado();
}

function getResDatas(){
  const p=document.getElementById('res-periodo').value;
  const hoje=new Date();
  if(p==='geral') return {d1:null,d2:null};
  if(p==='custom'){
    return {d1:document.getElementById('res-dt1').value,d2:document.getElementById('res-dt2').value};
  }
  const d1=new Date(hoje); d1.setDate(d1.getDate()-parseInt(p));
  return {d1:d1.toISOString().substring(0,10),d2:hoje.toISOString().substring(0,10)};
}

function inPeriodo(data,d1,d2){
  if(!d1&&!d2) return true;
  if(!data) return false;
  if(d1&&data<d1) return false;
  if(d2&&data>d2) return false;
  return true;
}

function rdResultado(){
  const eqId=document.getElementById('res-placa').value;
  const visao=document.getElementById('res-visao').value;
  const {d1,d2}=getResDatas();
  const equips=eqId?D.equips.filter(e=>e.id===eqId):D.equips;

  let totalRec=0,totalOS=0,totalDesp=0,totalSeg=0,totalDoc=0,totalDeprec=0;
  const rows=[];

  equips.forEach(eq=>{
    // + Medições recebidas (receitas)
    const meds=D.medicoes.filter(m=>m.eqId===eq.id&&m.st==='paga'&&inPeriodo(m.vc||m.de,d1,d2));
    const recMed=meds.reduce((s,m)=>s+(m.total||0),0);

    // - OS (custos)
    const oss=D.manutencoes.filter(m=>m.eqId===eq.id&&inPeriodo(m.en,d1,d2)&&!ehImpressao(m));
    const custoOS=oss.reduce((s,m)=>s+(m.custo==='cliente'?0:(m.lancs||[]).reduce((ss,l)=>ss+l.qtd*l.val,0)),0);

    // - Despesas vinculadas à placa
    const desps=D.despesas.filter(d=>d.placa===eq.placa&&inPeriodo(d.dt,d1,d2));
    const custoDesp=desps.reduce((s,d)=>s+(parseFloat(d.vl)||0),0);

    // - Depreciação (anual * período)
    const desval=parseFloat(eq.desval)||0;
    const vaql=parseFloat(eq.vaql)||0;
    let deprec=0;
    if(desval>0&&vaql>0){
      const dias=d1&&d2?(new Date(d2)-new Date(d1))/(1000*60*60*24):365;
      deprec=(vaql*(desval/100))*(dias/365);
    }

    const resultado=recMed-custoOS-custoDesp-deprec;
    totalRec+=recMed; totalOS+=custoOS; totalDesp+=custoDesp; totalDeprec+=deprec;

    rows.push({eq,recMed,custoOS,custoDesp,deprec,resultado,meds,oss,desps});
  });

  const totalRes=totalRec-totalOS-totalDesp-totalDeprec;

  // Cards de totais
  const cards=document.getElementById('res-cards');
  if(cards) cards.innerHTML=`
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">RECEITAS</div><div style="font-size:22px;font-weight:700;color:var(--gn)">${fmt(totalRec)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">CUSTOS OS</div><div style="font-size:22px;font-weight:700;color:var(--red)">${fmt(totalOS)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">DESPESAS</div><div style="font-size:22px;font-weight:700;color:var(--red)">${fmt(totalDesp)}</div></div>
    <div class="kpi"><div style="font-size:10px;color:var(--mt)">DEPRECIAÇÃO</div><div style="font-size:22px;font-weight:700;color:var(--yw)">${fmt(totalDeprec)}</div></div>
    <div class="kpi" style="border-color:${totalRes>=0?'var(--gn)':'var(--red)'}"><div style="font-size:10px;color:var(--mt)">RESULTADO</div><div style="font-size:22px;font-weight:700;color:${totalRes>=0?'var(--gn)':'var(--red)'}">${fmt(totalRes)}</div></div>
  `;

  // Tabela
  const tab=document.getElementById('res-tabela');
  if(!tab) return;
  if(!rows.length){tab.innerHTML='<div class="empty">Nenhum veículo/equipamento encontrado</div>';return;}

  if(visao==='simples'){
    tab.innerHTML=`<div class="tw"><table>
      <thead><tr><th>Placa</th><th>Modelo</th><th>Receitas</th><th>Custos OS</th><th>Despesas</th><th>Depreciação</th><th>Resultado</th></tr></thead>
      <tbody>${rows.map(r=>`<tr>
        <td><b>${r.eq.placa}</b></td>
        <td style="font-size:11px">${r.eq.mk} ${r.eq.mo}</td>
        <td style="color:var(--gn)">${fmt(r.recMed)}</td>
        <td style="color:var(--red)">${fmt(r.custoOS)}</td>
        <td style="color:var(--red)">${fmt(r.custoDesp)}</td>
        <td style="color:var(--yw)">${fmt(r.deprec)}</td>
        <td style="font-weight:700;color:${r.resultado>=0?'var(--gn)':'var(--red)'}">${fmt(r.resultado)}</td>
      </tr>`).join('')}
      <tr style="font-weight:700;background:var(--cd2)">
        <td colspan="2">TOTAL</td>
        <td style="color:var(--gn)">${fmt(totalRec)}</td>
        <td style="color:var(--red)">${fmt(totalOS)}</td>
        <td style="color:var(--red)">${fmt(totalDesp)}</td>
        <td style="color:var(--yw)">${fmt(totalDeprec)}</td>
        <td style="color:${totalRes>=0?'var(--gn)':'var(--red)'}">${fmt(totalRes)}</td>
      </tr>
      </tbody></table></div>`;
  } else {
    // Detalhado: show each row with breakdown
    tab.innerHTML=rows.map(r=>`
      <div class="panel" style="margin-bottom:12px">
        <div class="ph"><div class="pt">${r.eq.placa} — ${r.eq.mk} ${r.eq.mo}</div>
          <span style="font-weight:700;color:${r.resultado>=0?'var(--gn)':'var(--red)'}">${fmt(r.resultado)}</span>
        </div>
        <div class="tw"><table>
          <thead><tr><th>Tipo</th><th>Descrição</th><th>Data</th><th>Valor</th></tr></thead>
          <tbody>
            ${r.meds.map(m=>`<tr><td><span class="badge b-gn">+ Medição</span></td><td>${m.cl||'-'}</td><td style="font-size:10px">${fmtData(m.vc)}</td><td style="color:var(--gn)">${fmt(m.total)}</td></tr>`).join('')}
            ${r.oss.map(o=>`<tr><td><span class="badge b-rd">- OS ${o.osNum||''}</span></td><td>${o.tipo||'-'}</td><td style="font-size:10px">${o.en||'-'}</td><td style="color:var(--red)">${fmt((o.lancs||[]).reduce((s,l)=>s+l.qtd*l.val,0))}</td></tr>`).join('')}
            ${r.desps.map(d=>`<tr><td><span class="badge b-yw">- Despesa</span></td><td>${d.desc||d.cat||'-'}</td><td style="font-size:10px">${fmtData(d.dt)}</td><td style="color:var(--red)">${fmt(d.vl)}</td></tr>`).join('')}
            ${r.deprec>0?`<tr><td><span class="badge b-yw">- Depreciação</span></td><td>Desvalorização ${r.eq.desval}% a.a.</td><td>-</td><td style="color:var(--yw)">${fmt(r.deprec)}</td></tr>`:''}
          </tbody>
        </table></div>
      </div>`).join('');
  }
}

function imprimirResultado(){imprimirComOpcoes("Resultado por Placa");}

function checarForcaSenha(){
  const s=document.getElementById('senha-nova').value;
  const el=document.getElementById('senha-forca');
  if(!el) return;
  if(!s){el.innerHTML='';return;}
  const temLetra=/[A-Za-z]/.test(s);
  const temNum=/[0-9]/.test(s);
  const tam=s.length>=8;
  let pts=0;
  if(tam)pts++; if(temLetra)pts++; if(temNum)pts++;
  if(s.length>=12)pts++;
  if(/[^A-Za-z0-9]/.test(s))pts++;
  let cor,txt;
  if(!tam||!temLetra||!temNum){cor='var(--red)';txt='⚠️ Fraca — precisa 8+ caracteres, letra e número';}
  else if(pts<=3){cor='var(--or)';txt='🟡 Razoável';}
  else if(pts==4){cor='var(--bl)';txt='🔵 Boa';}
  else{cor='var(--gn)';txt='🟢 Forte';}
  el.style.color=cor;el.textContent=txt;
}


init();
</script>
